  it('keeps the billing framework flags mutually exclusive across actions', async () => {
    const { useChatStore } = loadChatStore();
    useChatStore.setState({
      selectedWorktree: { projectId: 'proj', worktreeId: 'wt' },
      worktreeChats: {
        'proj/wt': {
          activeTabId: 'chat',
          tabs: [makeTab({ id: 'chat', subscriptionBillingOverride: true })],
        },
      },
      chatStateSync: {
        'proj/wt': { phase: 'live', revision: 1 },
      },
    });

    // Enabling routing (the usage-limit banner path) must clear a prior
    // "Subscription" override so the two flags never coexist.
    useChatStore.getState().enableAiCreditsRouting({ scope: 'session' });
    const enabledTab =
      useChatStore.getState().worktreeChats['proj/wt']?.tabs[0];
    expect(enabledTab?.aiCreditsRouting?.active).toBe(true);
    expect(enabledTab?.subscriptionBillingOverride).toBeUndefined();
    expect(enabledTab?.billingExplicitlyChosen).toBe(true);

    // The billing toggle: AI Credits is a durable per-chat choice (persistent)
    // and clears the override.
    useChatStore.getState().selectBillingFramework('ai-credits');
    const aiCreditsTab =
      useChatStore.getState().worktreeChats['proj/wt']?.tabs[0];
    expect(aiCreditsTab?.aiCreditsRouting).toMatchObject({
      active: true,
      scope: 'persistent',
    });
    expect(aiCreditsTab?.subscriptionBillingOverride).toBeUndefined();
    expect(aiCreditsTab?.billingExplicitlyChosen).toBe(true);
    // The explicit choice is remembered globally so new chats/trees seed it.
    expect(savePreferencesMock).toHaveBeenCalledWith({
      lastChatBillingFramework: 'ai-credits',
    });

    // Selecting subscription clears routing and records the override.
    useChatStore.getState().selectBillingFramework('subscription');
    const subscriptionTab =
      useChatStore.getState().worktreeChats['proj/wt']?.tabs[0];
    expect(subscriptionTab?.aiCreditsRouting).toBeUndefined();
    expect(subscriptionTab?.subscriptionBillingOverride).toBe(true);
    expect(savePreferencesMock).toHaveBeenCalledWith({
      lastChatBillingFramework: 'subscription',
    });
    const aiCreditsCommand = chatCommandMock.mock.calls
      .map(([request]) => request)
      .find(
        (request) =>
          request.command.type === 'chat.patch_tab_settings' &&
          request.command.patch.aiCreditsRouting?.scope === 'persistent',
      );
    expect(aiCreditsCommand).toMatchObject({
      projectId: 'proj',
      worktreeId: 'wt',
      command: {
        type: 'chat.patch_tab_settings',
        tabId: 'chat',
        patch: { subscriptionBillingOverride: false },
      },
    });
    if (aiCreditsCommand?.command.type === 'chat.patch_tab_settings') {
      expect(aiCreditsCommand.command.patch.aiCreditsRouting).toMatchObject({
        active: true,
        scope: 'persistent',
      });
    }
    const subscriptionCommand = chatCommandMock.mock.calls
      .map(([request]) => request)
      .find(
        (request) =>
          request.command.type === 'chat.patch_tab_settings' &&
          request.command.patch.subscriptionBillingOverride === true,
      );
    expect(subscriptionCommand).toMatchObject({
      projectId: 'proj',
      worktreeId: 'wt',
      command: {
        type: 'chat.patch_tab_settings',
        tabId: 'chat',
        patch: {
          aiCreditsRouting: null,
          subscriptionBillingOverride: true,
        },
      },
    });

    await jest.advanceTimersByTimeAsync(500);
  });

  describe('stale AI Credits routing (CAN-4200)', () => {
    const SESSION_ROUTING = {
      active: true as const,
      scope: 'session' as const,
      activatedAt: 1_000,
    };

    function patchCommands(): unknown[] {
      return chatCommandMock.mock.calls.flatMap(([request]) =>
        request.command.type === 'chat.patch_tab_settings'
          ? [request.command.patch]
          : [],
      );
    }

    function seed(
      useChatStore: ReturnType<typeof loadChatStore>['useChatStore'],
      tab: Partial<ChatStoreModule.ChatTab>,
      live: boolean,
    ): void {
      useChatStore.setState({
        selectedWorktree: { projectId: 'proj', worktreeId: 'wt' },
        worktreeChats: {
          'proj/wt': {
            activeTabId: 'chat',
            tabs: [makeTab({ id: 'chat', ...tab })],
          },
        },
        chatStateSync: live
          ? { 'proj/wt': { phase: 'live', revision: 1 } }
          : {},
      });
    }

    it('persists a routing clear with no override or remembered default', () => {
      const { useChatStore } = loadChatStore();
      seed(useChatStore, { aiCreditsRouting: SESSION_ROUTING }, true);

      useChatStore.getState().clearAiCreditsRouting();

      const tab = useChatStore.getState().worktreeChats['proj/wt']?.tabs[0];
      expect(tab?.aiCreditsRouting).toBeUndefined();
      expect(tab?.subscriptionBillingOverride).toBeUndefined();
      expect(patchCommands()).toEqual([{ aiCreditsRouting: null }]);
      // No remembered default either: that is the picker's choice, not this.
      expect(savePreferencesMock).not.toHaveBeenCalled();
    });

    it('clears routing only locally when the scope is not live', () => {
      const { useChatStore } = loadChatStore();
      seed(useChatStore, { aiCreditsRouting: SESSION_ROUTING }, false);

      useChatStore.getState().clearAiCreditsRouting();

      expect(
        useChatStore.getState().worktreeChats['proj/wt']?.tabs[0]
          ?.aiCreditsRouting,
      ).toBeUndefined();
      expect(patchCommands()).toEqual([]);
    });

    it('sends nothing when the chat had no routing to clear', () => {
      const { useChatStore } = loadChatStore();
      seed(useChatStore, {}, true);

      useChatStore.getState().clearAiCreditsRouting();

      expect(patchCommands()).toEqual([]);
    });

    it('returns the activation stamp from enableAiCreditsRouting', () => {
      const { useChatStore } = loadChatStore();
      seed(useChatStore, {}, true);

      const activatedAt = useChatStore
        .getState()
        .enableAiCreditsRouting({ scope: 'session' });

      expect(activatedAt).toBe(
        useChatStore.getState().worktreeChats['proj/wt']?.tabs[0]
          ?.aiCreditsRouting?.activatedAt,
      );
    });

    it('records a late reset time on the matching session routing only', () => {
      const { useChatStore } = loadChatStore();
      seed(useChatStore, { aiCreditsRouting: SESSION_ROUTING }, true);

      useChatStore
        .getState()
        .setAiCreditsRoutingResetsAt({ resetsAt: 5_000, activatedAt: 1_000 });

      expect(
        useChatStore.getState().worktreeChats['proj/wt']?.tabs[0]
          ?.aiCreditsRouting,
      ).toEqual({ ...SESSION_ROUTING, resetsAt: 5_000 });
      expect(patchCommands()).toEqual([
        { aiCreditsRouting: { ...SESSION_ROUTING, resetsAt: 5_000 } },
      ]);
    });

    it.each([
      [
        'a newer activation',
        { aiCreditsRouting: { ...SESSION_ROUTING, activatedAt: 2_000 } },
      ],
      [
        'inactive routing',
        { aiCreditsRouting: { ...SESSION_ROUTING, active: false } },
      ],
      [
        'persistent routing',
        {
          aiCreditsRouting: {
            ...SESSION_ROUTING,
            scope: 'persistent' as const,
          },
        },
      ],
      ['no routing', {}],
    ])('ignores a late reset time for %s', (_label, tab) => {
      const { useChatStore } = loadChatStore();
      seed(useChatStore, tab, true);

      useChatStore
        .getState()
        .setAiCreditsRoutingResetsAt({ resetsAt: 5_000, activatedAt: 1_000 });

      expect(
        useChatStore.getState().worktreeChats['proj/wt']?.tabs[0]
          ?.aiCreditsRouting?.resetsAt,
      ).toBeUndefined();
      expect(patchCommands()).toEqual([]);
    });
  });

  it('refreshes in-memory model defaults on toggle so same-session new chats seed the choice', () => {
    const { useChatStore } = loadChatStore();
    useChatStore.setState({
      selectedWorktree: { projectId: 'sess', worktreeId: 'wt' },
      // Emulate a session that started with the routing safety net ON and no
      // remembered choice: a new tab would otherwise re-default to AI Credits.
      modelDefaults: {
        chatProvider: 'claude',
        chatModelByProvider: {
          claude: { model: 'claude-sonnet-4-6', thinkingLevel: 'high' },
          codex: { model: 'gpt-5.5', thinkingLevel: 'high' },
          ollama: null,
        },
        worktreeProvider: 'claude',
        worktreeModelByProvider: {
          claude: { model: 'claude-sonnet-4-6', thinkingLevel: 'high' },
          codex: { model: 'gpt-5.5', thinkingLevel: 'high' },
          ollama: null,
        },
      },
      worktreeChats: {
        'sess/wt': {
          activeTabId: 'chat',
          tabs: [makeTab({ id: 'chat' })],
        },
      },
    });

    // Toggling OFF must immediately update the in-memory default (not just the
    // persisted preference, which only re-hydrates on the next launch).
    useChatStore.getState().selectBillingFramework('subscription');
    expect(useChatStore.getState().modelDefaults?.billingFramework).toBe(
      'subscription',
    );

    // A new chat tab created later in the SAME session now seeds subscription
    // rather than falling through to the global routing mode.
    useChatStore.getState().createTab({ projectId: 'sess', worktreeId: 'wt' });
    const created = useChatStore.getState().worktreeChats['sess/wt'];
    const newTab = created?.tabs.find((c) => c.id === created.activeTabId);
    expect(newTab?.subscriptionBillingOverride).toBe(true);
    expect(newTab?.aiCreditsRouting).toBeUndefined();
  });

  it.each(['rejection', 'transport failure'])(
    'restores credits after subscription command %s (CAN-4759)',
    async (failure) => {
      const { useChatStore } = loadChatStore();
      const routing = {
        active: true as const,
        scope: 'session' as const,
        activatedAt: 1,
      };
      chatCommandMock.mockImplementationOnce(
        (request): Promise<ChatCommandResponse> => {
          if (failure === 'transport failure')
            return Promise.reject(new Error('offline'));
          return Promise.resolve({
            commandId: request.commandId,
            revision: 1,
            outcome: 'rejected',
          });
        },
      );
      useChatStore.setState({
        selectedWorktree: { projectId: 'proj', worktreeId: 'wt' },
        worktreeChats: {
          'proj/wt': {
            activeTabId: 'chat',
            tabs: [makeTab({ id: 'chat', aiCreditsRouting: routing })],
          },
        },
        chatStateSync: { 'proj/wt': { phase: 'live', revision: 1 } },
      });
      useChatStore.getState().selectBillingFramework('subscription');
      expect(
        useChatStore.getState().worktreeChats['proj/wt']?.tabs[0]
          ?.subscriptionBillingOverride,
      ).toBe(true);
      for (let i = 0; i < 10; i += 1) await Promise.resolve();
      const tab = useChatStore.getState().worktreeChats['proj/wt']?.tabs[0];
      expect(tab?.aiCreditsRouting).toEqual(routing);
      expect(tab?.subscriptionBillingOverride).toBeUndefined();
      expect(useChatStore.getState().chatStateNotices['proj/wt']?.kind).toBe(
        'command_failed',
      );
    },
  );

