  it.each(['create', 'prepare'])(
    'keeps overlapping Cursor proposals in one plan while %s is pending',
    async (stage) => {
      const { useChatStore } = loadChatStore();
      let finishFirst: () => void = () => {};
      const first = new Promise<void>((resolve) => {
        finishFirst = resolve;
      });
      const plan = await activityPlansCreateMock.getMockImplementation()?.({});
      if (!plan) throw new Error('Missing fixture plan');
      activityPlansCreateMock.mockImplementationOnce(async () => {
        if (stage === 'create') await first;
        return plan;
      });
      const instruction = {
        instruction: {
          id: 'plan-file-location:plan-created',
          text: 'Use /tmp/plan.md for future plan reads and updates.',
        },
      };
      preparePlanFileSystemInstructionMock.mockImplementationOnce(async () => {
        if (stage === 'prepare') await first;
        return instruction;
      });
      activityPlansUpdateMock.mockResolvedValue({
        ...plan,
        latestRevisionNumber: 2,
        revisions: [
          ...plan.revisions,
          { ...plan.revisions[0], revisionNumber: 2, content: 'Revised plan' },
        ],
      });
      useChatStore.setState({
        selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
        worktreeChats: {
          'project/worktree': {
            activeTabId: 'chat',
            tabs: [makeTab({ planMode: true, providerType: 'cursor' })],
          },
        },
      });
      const event = {
        requestId: 'older-request',
        projectId: 'project',
        worktreeId: 'worktree',
        chatId: 'chat',
        source: 'cursor' as const,
        reviewMode: 'proposal' as const,
        toolInput: { plan: 'A plan', source: 'cursor', reviewMode: 'proposal' },
      };
      useChatStore.getState().handlePlanExitRequest(event);
      await jest.advanceTimersByTimeAsync(0);
      useChatStore.getState().handlePlanExitRequest({
        ...event,
        requestId: 'newer-request',
        toolInput: { ...event.toolInput, plan: 'Revised plan' },
      });
      await jest.advanceTimersByTimeAsync(0);
      finishFirst();
      await jest.advanceTimersByTimeAsync(0);
      expect(activityPlansCreateMock).toHaveBeenCalledTimes(1);
      expect(activityPlansUpdateMock).toHaveBeenCalledTimes(1);
      expect(activityPlansUpdateMock).toHaveBeenCalledWith(
        expect.objectContaining({
          planId: plan.id,
          proposalRequestId: 'newer-request',
          content: 'Revised plan',
        }),
      );
      expect(
        useChatStore.getState().worktreeChats['project/worktree']?.tabs[0],
      ).toMatchObject({
        pendingPlanExitRequestId: 'newer-request',
        trackedPlanId: plan.id,
        latestRevisionNumber: 2,
      });
      const commands = chatCommandMock.mock.calls
        .map(([request]) => request)
        .filter((request) =>
          request.commandId.startsWith('renderer-cursor-plan-'),
        );
      expect(commands).toHaveLength(1);
      const command = commands[0]?.command;
      expect(command?.type).toBe('chat.patch_tab_settings');
      if (command?.type !== 'chat.patch_tab_settings')
        throw new Error('Expected projection patch');
      expect(command.expectedPendingPlanExitRequestId).toBe('newer-request');
    },
  );

