  // ---------------------------------------------------------------------
  // CAN-1814 PR 7. A send the host REFUSES on a broken auth dependency has to
  // land in the transcript as the reconnect card, not as prose.
  //
  // The refusal arrives as `ChatSendMessageResult.refusedAuthDependencies`
  // rather than a rejection, so the failures survive the IPC boundary intact
  // and are attached to the block `ChatBlockRenderer` already routes to
  // `AuthRecoveryCard`. The card renders in the transcript, at the point of
  // refusal, directly under the message that was refused -- there is no
  // assistant turn to anchor to, and that is where the user is already
  // looking.
  // ---------------------------------------------------------------------
  it("attaches the refused send's blockers to the transcript block", async () => {
    const { useChatStore } = loadChatStore();
    const key = 'project/worktree';
    sendMessageMock.mockResolvedValueOnce({
      refusedAuthDependencies: {
        message:
          'Prod MCP server needs to be reconnected before this message can run.',
        failures: [REFUSED_MCP_BLOCKER],
      },
    });

    useChatStore.setState({
      selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
      worktreeChats: {
        [key]: { activeTabId: 'chat', tabs: [makeTab({ id: 'chat' })] },
      },
    });

    await useChatStore.getState().sendMessage('look up the record');

    const tab = useChatStore.getState().worktreeChats[key]?.tabs[0];
    expect(tab?.status).toBe('error');
    const lastMessage = tab?.messages[tab.messages.length - 1];
    expect(lastMessage?.role).toBe('system');
    expect(lastMessage?.blocks).toEqual([
      {
        type: 'text',
        text: 'Prod MCP server needs to be reconnected before this message can run.',
        authFailures: [REFUSED_MCP_BLOCKER],
      },
    ]);
  });

  it('carries every blocker of a multi-dependency refusal into one block', async () => {
    const { useChatStore } = loadChatStore();
    const key = 'project/worktree';
    sendMessageMock.mockResolvedValueOnce({
      refusedAuthDependencies: {
        message:
          'Prod MCP server and Staging MCP server need to be reconnected before this message can run.',
        failures: [REFUSED_MCP_BLOCKER, REFUSED_SCOPE_BLOCKER],
      },
    });

    useChatStore.setState({
      selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
      worktreeChats: {
        [key]: { activeTabId: 'chat', tabs: [makeTab({ id: 'chat' })] },
      },
    });

    await useChatStore.getState().sendMessage('look up the record');

    const tab = useChatStore.getState().worktreeChats[key]?.tabs[0];
    const lastBlock = tab?.messages[tab.messages.length - 1]?.blocks[0];
    expect(lastBlock).toMatchObject({
      // A non-recoverable blocker travels ALONGSIDE a recoverable one: the
      // card renders a row for each and decides per row whether a login
      // affordance is allowed. Dropping it would hide work still to do.
      authFailures: [REFUSED_MCP_BLOCKER, REFUSED_SCOPE_BLOCKER],
    });
  });

