  it('sends a streaming follow-up to the host queue and clears its accepted attachments', async () => {
    const { useChatStore } = loadChatStore();
    const { chatBannerKey, useAiCreditsBannerStore } = jest.requireActual<
      typeof AiCreditsBannerStoreModule
    >('../stores/aiCreditsBannerStore');
    const key = 'project/worktree';
    const target = {
      projectId: 'project',
      worktreeId: 'worktree',
      chatId: 'chat',
    };
    getResolvedDefaultMock.mockResolvedValue('auto');

    useChatStore.setState({
      selectedWorktree: {
        projectId: 'project',
        worktreeId: 'worktree',
      },
      approvalDefaultsCache: {},
      worktreeChats: {
        [key]: {
          activeTabId: 'chat',
          tabs: [
            makeTab({
              id: 'chat',
              status: 'streaming',
              pendingAttachments: [
                {
                  filename: 'queued.png',
                  absolutePath: '/attachments/queued.png',
                },
              ],
              pendingRevertAttachmentPath: '/attachments/revert.md',
              llmProviderUsageLimitBanner: {
                provider: 'claude',
                message: 'Claude usage limit reached',
                detectedAt: 1_776_000_000_000,
                dismissKey: 'usage-limit:claude:request-1',
              },
            }),
          ],
        },
      },
    });
    useAiCreditsBannerStore
      .getState()
      .setUsageLimit(target, { provider: 'claude' });
    const queuedWithoutDispatch = jest.fn();

    await useChatStore
      .getState()
      .sendMessage('queue this', undefined, undefined, undefined, {
        onQueuedWithoutDispatch: queuedWithoutDispatch,
      });

    // Main's durable input-delivery queue owns the follow-up.
    expect(queuedWithoutDispatch).toHaveBeenCalledTimes(1);
    expect(queuedWithoutDispatch).toHaveBeenCalledWith('host');
    const queuedTab = useChatStore.getState().worktreeChats[key]?.tabs[0];
    expect(sendMessageMock).toHaveBeenCalledWith(
      expect.objectContaining({
        text: 'queue this',
        attachmentPaths: ['/attachments/revert.md', '/attachments/queued.png'],
        approvalMode: 'auto',
        executionHarness: 'claude',
      }),
    );
    expect(queuedTab?.queuedMessages).toEqual([]);
    expect(queuedTab?.pendingAttachments).toBeUndefined();
    expect(queuedTab?.pendingRevertAttachmentPath).toBeUndefined();
    expect(queuedTab?.executionHarness).toBe('claude');
    // Handing the message to the host queue is the dispatch from the
    // renderer's point of view: the usage-limit banner retires immediately.
    expect(queuedTab?.llmProviderUsageLimitBanner).toBeUndefined();
    expect(
      useAiCreditsBannerStore.getState().usageLimitByChat[
        chatBannerKey(target)
      ],
    ).toBeUndefined();

    useChatStore.getState().handleChatEvent({
      ...target,
      data: {
        type: 'result',
        is_error: false,
        result: 'done',
      },
    });
    await Promise.resolve();
    await Promise.resolve();

    const dispatchedTab = useChatStore.getState().worktreeChats[key]?.tabs[0];
    expect(sendMessageMock).toHaveBeenCalledWith(
      expect.objectContaining({
        projectId: 'project',
        worktreeId: 'worktree',
        chatId: 'chat',
        text: 'queue this',
      }),
    );
    expect(dispatchedTab?.llmProviderUsageLimitBanner).toBeUndefined();
    expect(
      dispatchedTab?.dismissedLlmProviderUsageLimitBannerKey,
    ).toBeUndefined();
    expect(
      useAiCreditsBannerStore.getState().usageLimitByChat[
        chatBannerKey(target)
      ],
    ).toBeUndefined();
  });

