  describe('host-queue send failure toast', () => {
    type AddToastArgs = [
      string,
      'error' | 'info' | 'success' | 'warning',
      (() => void)?,
      GitHubStoreModule.ToastMeta?,
    ];

    function loadWithToasts(): {
      useChatStore: typeof ChatStoreModule.useChatStore;
      useProjectsStore: typeof ProjectsStoreModule.useProjectsStore;
      useNavigationStore: typeof NavigationStoreModule.useNavigationStore;
      toasts: () => AddToastArgs[];
    } {
      const { chatStore, githubStore, projectsStore, navigationStore } =
        loadChatAndGitHubStores();
      // In-app toasts are gated on notification preferences that are off in
      // this suite, so capture what the slice asks the store to show.
      const addToast = jest.fn<void, AddToastArgs>();
      githubStore.useGitHubStore.setState({ addToast });
      return {
        useChatStore: chatStore.useChatStore,
        useProjectsStore: projectsStore.useProjectsStore,
        useNavigationStore: navigationStore.useNavigationStore,
        toasts: () => addToast.mock.calls,
      };
    }

    function seedStreamingChat(
      useChatStore: typeof ChatStoreModule.useChatStore,
      scope: { projectId: string; worktreeId: string } = {
        projectId: 'project',
        worktreeId: 'worktree',
      },
    ): void {
      useChatStore.setState({
        selectedWorktree: scope,
        worktreeChats: {
          [`${scope.projectId}/${scope.worktreeId}`]: {
            activeTabId: 'chat',
            tabs: [
              makeTab({
                id: 'chat',
                title: 'Fix the login bug',
                status: 'streaming',
              }),
            ],
          },
        },
      });
    }

    async function settleRejectedSend(): Promise<void> {
      await Promise.resolve();
      await Promise.resolve();
    }

    let consoleError: jest.SpyInstance;
    beforeEach(() => {
      consoleError = jest
        .spyOn(console, 'error')
        .mockImplementation(() => undefined);
    });
    afterEach(() => {
      consoleError.mockRestore();
    });

    it('attributes a failed typed send to its chat through the toast header', async () => {
      const { useChatStore, useProjectsStore, useNavigationStore, toasts } =
        loadWithToasts();
      useProjectsStore.setState({
        hasHydratedProjects: true,
        projects: [makeSidebarItem('project', 'worktree')],
      });
      seedStreamingChat(useChatStore);
      sendMessageMock.mockRejectedValueOnce(new Error('ipc failed'));

      await useChatStore.getState().sendMessage('queue this');
      await settleRejectedSend();

      expect(toasts()).toEqual([
        [
          "Couldn't send your message. Try again.",
          'error',
          expect.any(Function),
          // No category: a send failure must not follow the Chat notification
          // preference the way chat activity toasts do.
          {
            workspaceName: 'Project',
            projectId: 'project',
            worktreeId: 'worktree',
            chatId: 'chat',
          },
        ],
      ]);

      // Clicking the toast opens the chat the same way the chat activity
      // toast does.
      useNavigationStore.getState().openSettings();
      toasts()[0]?.[2]?.();
      expect(useNavigationStore.getState().activePage).toBe('main');
    });

    it('attributes a Work chat to its workspace', async () => {
      const { useChatStore, useProjectsStore, toasts } = loadWithToasts();
      const registry = jest.requireActual<typeof CoworkRegistryModule>(
        '../lib/cowork-registry',
      );
      registry.registerCoworkWorkspaceIds(['cowork-project']);
      useProjectsStore.setState({
        hasHydratedProjects: true,
        projects: [
          {
            type: 'cowork',
            id: 'cowork-project',
            name: 'Finance',
            color: '#000000',
            collapsed: false,
            order: 0,
          },
        ],
      });
      seedStreamingChat(useChatStore, {
        projectId: 'cowork-project',
        worktreeId: 'entry',
      });
      sendMessageMock.mockRejectedValueOnce(new Error('ipc failed'));
      try {
        await useChatStore.getState().sendMessage('queue this');
        await settleRejectedSend();

        expect(toasts()).toEqual([
          [
            "Couldn't send your message. Try again.",
            'error',
            expect.any(Function),
            {
              workspaceName: 'Finance',
              projectId: 'cowork-project',
              worktreeId: 'entry',
              chatId: 'chat',
            },
          ],
        ]);
      } finally {
        registry.registerCoworkWorkspaceIds([]);
      }
    });
  });

  it('waits for streaming host-queue acceptance when dispatch failure must propagate', async () => {
    const { useChatStore } = loadChatStore();
    let acceptDispatch: (() => void) | undefined;
    sendMessageMock.mockImplementationOnce(
      () =>
        new Promise<ChatSendMessageResult>((resolve) => {
          acceptDispatch = (): void => resolve(ACCEPTED_CHAT_SEND_RESULT);
        }),
    );
    useChatStore.setState({
      selectedWorktree: {
        projectId: 'project',
        worktreeId: 'worktree',
      },
      worktreeChats: {
        'project/worktree': {
          activeTabId: 'chat',
          tabs: [makeTab({ id: 'chat', status: 'streaming' })],
        },
      },
    });

    let settled = false;
    const dispatch = useChatStore
      .getState()
      .sendMessage('queue this', undefined, undefined, undefined, {
        throwOnDispatchFailure: true,
      })
      .then(() => {
        settled = true;
      });
    await Promise.resolve();
    await Promise.resolve();
    expect(sendMessageMock).toHaveBeenCalledTimes(1);
    expect(settled).toBe(false);

    const { toActiveTranscriptView } = jest.requireActual<typeof ChatViewTypes>(
      '../components/chat/types',
    );
    const pendingTab =
      useChatStore.getState().worktreeChats['project/worktree'].tabs[0];
    expect(toActiveTranscriptView(pendingTab).queuedMessages).toEqual([
      expect.objectContaining({ text: 'queue this' }),
    ]);

    useChatStore.getState().handleChatQueueUpdated({
      projectId: 'project',
      worktreeId: 'worktree',
      chatId: 'chat',
      queue: [
        {
          id: 'host-accepted',
          text: 'queue this',
          origin: 'desktop',
          enqueuedAtMs: Date.now(),
        },
      ],
    });
    const acceptedTab =
      useChatStore.getState().worktreeChats['project/worktree'].tabs[0];
    expect(toActiveTranscriptView(acceptedTab).queuedMessages).toEqual([
      expect.objectContaining({
        text: 'queue this',
        hostQueueEntryId: 'host-accepted',
      }),
    ]);

    acceptDispatch?.();
    await dispatch;
    expect(settled).toBe(true);
  });

