  describe('with live managed delegates', () => {
    const DELEGATES_NOTICE =
      'Delegates are still running. Open background work and stop them to close this chat.';

    beforeEach(() => {
      // Refusal toasts arm auto-dismiss timers; the suite's afterEach flushes
      // fake timers.
      installFakeTimers({ doNotFake: ['queueMicrotask', 'nextTick'] });
    });

    function loadWithDelegates(): {
      useChatStore: typeof ChatStoreModule.useChatStore;
      useGitHubStore: typeof GitHubStoreModule.useGitHubStore;
      delegations: typeof DelegationActivityStoreModule;
    } {
      const { chatStore, githubStore } = loadChatAndGitHubStores();
      const delegations = jest.requireActual<
        typeof DelegationActivityStoreModule
      >('../stores/delegationActivityStore');
      githubStore.useGitHubStore.setState({ toasts: [], notifications: [] });
      return {
        useChatStore: chatStore.useChatStore,
        useGitHubStore: githubStore.useGitHubStore,
        delegations,
      };
    }

    function contentfulTab(id: string): ChatStoreModule.ChatTab {
      return makeTab({
        id,
        title: id,
        messages: [
          {
            id: `${id}-m1`,
            role: 'user',
            blocks: [{ type: 'text', text: 'Hi' }],
            timestamp: 1,
          },
        ],
      });
    }

    it('keeps an idle chat with live delegates open on close and says why', async () => {
      const { useChatStore, useGitHubStore, delegations } = loadWithDelegates();
      const key = 'project/worktree';
      useChatStore.setState({
        selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
        worktreeChats: {
          [key]: {
            activeTabId: 'root-chat',
            tabs: [contentfulTab('root-chat'), makeTab({ id: 'other' })],
          },
        },
      });
      delegations.useDelegationActivityStore.getState().applyActivity({
        projectId: 'project',
        worktreeId: 'worktree',
        chatId: 'root-chat',
        live: 1,
        queued: 0,
      });

      useChatStore.getState().closeTab('root-chat');
      await flushChatStoreAsyncWork();

      expect(archiveTabMock).not.toHaveBeenCalled();
      expect(
        useChatStore.getState().worktreeChats[key]?.tabs.map((t) => t.id),
      ).toEqual(['root-chat', 'other']);
      expect(
        useGitHubStore.getState().toasts.map((toast) => toast.message),
      ).toEqual([DELEGATES_NOTICE]);

      // Once its delegates finish, the same close goes through.
      delegations.useDelegationActivityStore.getState().applyActivity({
        projectId: 'project',
        worktreeId: 'worktree',
        chatId: 'root-chat',
        live: 0,
        queued: 0,
      });
      useChatStore.getState().closeTab('root-chat');
      await flushChatStoreAsyncWork();

      expect(archiveTabMock).toHaveBeenCalledTimes(1);
      expect(
        useChatStore.getState().worktreeChats[key]?.tabs.map((t) => t.id),
      ).toEqual(['other']);
    });

    it('skips a chat with live delegates in a bulk close and says why', async () => {
      const { useChatStore, useGitHubStore, delegations } = loadWithDelegates();
      const key = 'project/worktree';
      useChatStore.setState({
        selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
        worktreeChats: {
          [key]: {
            activeTabId: 'keeper',
            tabs: [
              contentfulTab('root-chat'),
              contentfulTab('idle-chat'),
              makeTab({ id: 'keeper' }),
            ],
          },
        },
      });
      delegations.useDelegationActivityStore.getState().applyActivity({
        projectId: 'project',
        worktreeId: 'worktree',
        chatId: 'root-chat',
        live: 0,
        queued: 1,
      });

      useChatStore.getState().closeTabs(['root-chat', 'idle-chat'], {
        projectId: 'project',
        worktreeId: 'worktree',
      });
      await flushChatStoreAsyncWork();

      expect(
        useChatStore.getState().worktreeChats[key]?.tabs.map((t) => t.id),
      ).toEqual(['root-chat', 'keeper']);
      expect(
        useGitHubStore.getState().toasts.map((toast) => toast.message),
      ).toEqual([DELEGATES_NOTICE]);
    });

    it('keeps a streaming chat silent: its spinner already says why', async () => {
      const { useChatStore, useGitHubStore } = loadWithDelegates();
      const key = 'project/worktree';
      useChatStore.setState({
        selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
        worktreeChats: {
          [key]: {
            activeTabId: 'streaming-chat',
            tabs: [
              { ...contentfulTab('streaming-chat'), status: 'streaming' },
              makeTab({ id: 'other' }),
            ],
          },
        },
      });

      useChatStore.getState().closeTab('streaming-chat');
      await flushChatStoreAsyncWork();

      expect(useGitHubStore.getState().toasts).toEqual([]);
    });
  });

