  it("defers a completed turn's auto-archive while delegates run, then archives when they finish", async () => {
    const { useChatStore } = loadChatStore();
    const delegations = jest.requireActual<
      typeof DelegationActivityStoreModule
    >('../stores/delegationActivityStore');
    const revisioned = jest.requireActual<typeof RevisionedSliceModule>(
      '../stores/chat/slices/revisioned',
    );
    const disposeReevaluation = revisioned.installAutoArchiveAfterDelegates();
    const key = 'project/worktree';
    const setDelegates = (live: number): void => {
      delegations.useDelegationActivityStore.getState().applyActivity({
        projectId: 'project',
        worktreeId: 'worktree',
        chatId: 'marked',
        live,
        queued: 0,
      });
    };
    try {
      useChatStore.setState({
        selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
        worktreeChats: {
          [key]: {
            activeTabId: 'keeper',
            tabs: [
              makeTab({ id: 'marked', autoArchive: true }),
              makeTab({ id: 'keeper' }),
            ],
          },
        },
      });
      setDelegates(1);

      useChatStore.getState().handleChatEvent({
        projectId: 'project',
        worktreeId: 'worktree',
        chatId: 'marked',
        data: { type: 'result', is_error: false, result: 'Done' },
      });
      await flushChatStoreAsyncWork();

      // Deferred, not given up: the chat stays open and keeps its flag.
      expect(archiveTabMock).not.toHaveBeenCalled();
      const marked = useChatStore
        .getState()
        .worktreeChats[key]?.tabs.find((tab) => tab.id === 'marked');
      expect(marked?.autoArchive).toBe(true);

      // Another delegate change that is not the finish does nothing.
      setDelegates(2);
      await flushChatStoreAsyncWork();
      expect(archiveTabMock).not.toHaveBeenCalled();

      setDelegates(0);
      await flushChatStoreAsyncWork();

      expect(archiveTabMock).toHaveBeenCalledTimes(1);
      expect(archiveTabMock).toHaveBeenCalledWith(
        expect.objectContaining({
          projectId: 'project',
          worktreeId: 'worktree',
          tabId: 'marked',
          keepSession: true,
        }),
      );
      expect(
        useChatStore.getState().worktreeChats[key]?.tabs.map((tab) => tab.id),
      ).toEqual(['keeper']);
    } finally {
      disposeReevaluation();
    }
  });

