  it('retries a failed eager starter creation once for concurrent later sends', async () => {
    const { useChatStore } = loadChatStore();
    const key = 'project/worktree';
    let resolveRetry: ((response: ChatCommandResponse) => void) | undefined;
    chatCommandMock
      .mockResolvedValueOnce({
        commandId: 'failed-eager-creation',
        revision: 1,
        outcome: 'rejected',
      })
      .mockImplementationOnce(
        () =>
          new Promise((resolve) => {
            resolveRetry = resolve;
          }),
      );

    useChatStore.setState({
      selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
      worktreeChats: {
        [key]: {
          activeTabId: 'chat',
          tabs: [makeTab({ id: 'chat', pendingInitialCreation: true })],
        },
      },
      chatStateSync: {
        [key]: { phase: 'live', revision: 1 },
      },
    });

    await useChatStore.getState().ensureWorktreeHasChatTab({
      projectId: 'project',
      worktreeId: 'worktree',
    });
    expect(
      useChatStore.getState().worktreeChats[key]?.tabs[0]
        ?.pendingInitialCreation,
    ).toBe(true);

    const firstSend = useChatStore.getState().sendMessage('first retry prompt');
    const secondSend = useChatStore
      .getState()
      .sendMessage('second retry prompt');
    await flushChatStoreAsyncWork();

    expect(resolveRetry).toBeDefined();
    resolveRetry?.({
      commandId: 'successful-eager-creation-retry',
      revision: 2,
      outcome: 'applied',
    });
    await Promise.all([firstSend, secondSend]);

    const createTabCalls = chatCommandMock.mock.calls.filter(
      ([request]) => request.command.type === 'chat.create_tab',
    );
    expect(createTabCalls).toHaveLength(2);
    expect(sendMessageMock).toHaveBeenCalledTimes(2);
    expect(
      useChatStore.getState().worktreeChats[key]?.tabs[0]
        ?.pendingInitialCreation,
    ).toBeUndefined();
  });

