  it('queues a Claude Code terminal prompt before launch and drains it only once the CLI is ready for input', async () => {
    const { useChatStore, initializeClaudeTerminalChatSync } = loadChatStore();
    const { useClaudeTerminalStore, __resetClaudeTerminalStoreForTests } =
      jest.requireActual<typeof ClaudeTerminalStoreModule>(
        '../stores/claudeTerminalStore',
      );
    const key = 'project/worktree';
    const chatKey = `${key}/chat`;
    const dispose = initializeClaudeTerminalChatSync();
    const launchResponse = {
      terminalId: 'terminal-1',
      sessionKey: 'session-key',
      sdkSessionId: 'terminal-generated-sdk',
      state: {
        terminalId: 'terminal-1',
        sessionKey: 'session-key',
        sdkSessionId: 'terminal-generated-sdk',
        turnState: 'idle' as const,
      },
    };
    let resolveLaunch: ((response: typeof launchResponse) => void) | undefined;
    claudeTerminalLaunchMock.mockImplementationOnce(
      () =>
        new Promise<typeof launchResponse>((resolve) => {
          resolveLaunch = resolve;
        }),
    );

    try {
      useChatStore.setState({
        selectedWorktree: {
          projectId: 'project',
          worktreeId: 'worktree',
        },
        worktreeChats: {
          [key]: {
            activeTabId: 'chat',
            tabs: [
              makeTab({
                id: 'chat',
                interfaceMode: 'claude-code',
                providerType: 'claude',
                messages: [],
              }),
            ],
          },
        },
      });

      await useChatStore.getState().sendMessage('Queue before launch');

      expect(sendMessageMock).not.toHaveBeenCalled();
      expect(terminalWriteMock).not.toHaveBeenCalled();
      expect(
        useChatStore.getState().worktreeChats[key]?.tabs[0]?.queuedMessages,
      ).toEqual([expect.objectContaining({ text: 'Queue before launch' })]);

      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
      expect(claudeTerminalLaunchMock).toHaveBeenCalledWith(
        expect.objectContaining({
          projectId: 'project',
          worktreeId: 'worktree',
          chatId: 'chat',
          // The first prompt rides along as the CLI's initial positional
          // argument so a fresh launch does not need the TUI replay path.
          initialPrompt: 'Queue before launch',
        }),
      );

      resolveLaunch?.(launchResponse);
      await jest.advanceTimersByTimeAsync(600);

      // The launch resolved without consuming the initial prompt, but the
      // freshly spawned CLI has not issued a hook callback yet — pasting now
      // would be swallowed by startup, so the prompt stays queued.
      expect(terminalWriteMock).not.toHaveBeenCalled();
      expect(
        useChatStore.getState().worktreeChats[key]?.tabs[0]?.queuedMessages,
      ).toEqual([expect.objectContaining({ text: 'Queue before launch' })]);

      // First hook callback: main reports the CLI is ready for input.
      claudeTerminalGetStateMock.mockResolvedValue({
        terminalId: 'terminal-1',
        sessionKey: 'session-key',
        sdkSessionId: 'terminal-generated-sdk',
        turnState: 'idle',
        readyForInput: true,
      });
      const launchedState = useClaudeTerminalStore.getState().byChat[chatKey];
      expect(launchedState).toBeDefined();
      if (launchedState) {
        useClaudeTerminalStore.setState({
          byChat: {
            ...useClaudeTerminalStore.getState().byChat,
            [chatKey]: { ...launchedState, readyForInput: true },
          },
        });
      }
      // The readiness transition drains the queue through the TUI write
      // path (clear sequence timers included).
      await jest.advanceTimersByTimeAsync(600);

      expect(sendMessageMock).not.toHaveBeenCalled();
      const allWriteRequests = terminalWriteMock.mock.calls.map(
        (call) => call[0],
      );
      const pasteIndex = allWriteRequests.findIndex((request) =>
        request?.data.includes('Queue before launch'),
      );
      expect(allWriteRequests[pasteIndex]).toMatchObject({
        terminalId: 'terminal-1',
      });
      // The submitting Enter follows the paste as a separate delayed write.
      expect(allWriteRequests[pasteIndex + 1]).toMatchObject({
        terminalId: 'terminal-1',
        data: '\r',
      });
      expect(
        useChatStore.getState().worktreeChats[key]?.tabs[0]?.queuedMessages,
      ).toEqual([]);
      // Flush the drain's debounced title save so it cannot leak into later
      // tests that assert no saves were scheduled for this worktree.
      await jest.advanceTimersByTimeAsync(600);
    } finally {
      dispose();
      __resetClaudeTerminalStoreForTests();
    }
  });

