  it('delivers a consumed launch prompt once when its transcript commit fails', async () => {
    const { useChatStore } = loadChatStore();
    const key = 'project/worktree';
    claudeTerminalLaunchMock.mockResolvedValueOnce({
      terminalId: 'terminal-1',
      sessionKey: 'session-key',
      sdkSessionId: 'terminal-generated-sdk',
      initialPromptSubmitted: true,
      state: {
        terminalId: 'terminal-1',
        sessionKey: 'session-key',
        sdkSessionId: 'terminal-generated-sdk',
        turnState: 'idle',
      },
    });
    chatCommandMock.mockImplementation((request) =>
      Promise.resolve(
        request.command.type === 'chat.commit_terminal_initial_prompt'
          ? {
              commandId: 'terminal-prompt-commit',
              revision: 1,
              outcome: 'rejected',
              reason: 'persistence unavailable',
            }
          : { commandId: 'other-command', revision: 2, outcome: 'applied' },
      ),
    );
    useChatStore.setState({
      selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
      worktreeChats: {
        [key]: {
          activeTabId: 'chat',
          tabs: [
            makeTab({
              id: 'chat',
              interfaceMode: 'claude-code',
              providerType: 'claude',
              pendingSystemInstructions: [
                { id: 'instruction-1', text: 'Use /tmp/plan.md.' },
              ],
            }),
          ],
        },
      },
      chatStateSync: { [key]: { phase: 'live', revision: 1 } },
    });
    const accepted = jest.fn();
    const rejected = jest.fn();
    const queued = jest.fn();

    await useChatStore
      .getState()
      .sendMessage('Composer prompt', undefined, undefined, undefined, {
        onDispatchAccepted: accepted,
        onDispatchRejected: rejected,
        onQueuedWithoutDispatch: queued,
      });
    await jest.advanceTimersByTimeAsync(600);

    expect(
      chatCommandMock.mock.calls.some(
        ([request]) =>
          request.command.type === 'chat.commit_terminal_initial_prompt',
      ),
    ).toBe(true);
    // The CLI took the prompt as its initial argument: the send is delivered,
    // even though the transcript could not record it.
    expect(accepted).toHaveBeenCalledTimes(1);
    expect(rejected).not.toHaveBeenCalled();
    expect(queued).not.toHaveBeenCalled();
    const tab = useChatStore.getState().worktreeChats[key]?.tabs[0];
    // The queued copy becomes the visible user turn instead of waiting to be
    // replayed into the terminal once Claude's turn ends.
    expect(tab?.queuedMessages).toEqual([]);
    expect(tab?.messages).toEqual([
      expect.objectContaining({
        role: 'user',
        blocks: [{ type: 'text', text: 'Composer prompt' }],
      }),
      expect.objectContaining({
        role: 'system',
        blocks: [expect.objectContaining({ type: 'turn_timer' })],
      }),
    ]);
    // The instructions rode along in the initial prompt.
    expect(tab?.pendingSystemInstructions).toBeUndefined();
    expect(terminalWriteMock).not.toHaveBeenCalled();
  });

