  it('relaunches with the prompt as initial argument when the renderer snapshot is stale and the process is gone', async () => {
    const { useChatStore } = loadChatStore();
    const { useClaudeTerminalStore, __resetClaudeTerminalStoreForTests } =
      jest.requireActual<typeof ClaudeTerminalStoreModule>(
        '../stores/claudeTerminalStore',
      );
    const key = 'project/worktree';
    const chatKey = `${key}/chat`;
    // Main is authoritative and reports no live runtime (e.g. the idle TTL
    // reaped the process, or the app restarted).
    claudeTerminalGetStateMock.mockResolvedValue(undefined);
    claudeTerminalLaunchMock.mockImplementationOnce(
      () =>
        new Promise(() => {
          // Keep launch pending so the test can assert the dispatch shape.
        }),
    );

    try {
      // The renderer store still remembers a ready terminal.
      useClaudeTerminalStore.setState({
        byChat: {
          [chatKey]: {
            projectId: 'project',
            worktreeId: 'worktree',
            chatId: 'chat',
            terminalId: 'stale-terminal',
            sessionKey: 'stale-session',
            sdkSessionId: 'stale-sdk',
            turnState: 'idle',
            readyForInput: true,
            launchStatus: 'ready',
          },
        },
        terminalIdIndex: { 'stale-terminal': chatKey },
      });
      useChatStore.setState({
        selectedWorktree: {
          projectId: 'project',
          worktreeId: 'worktree',
        },
        worktreeChats: {
          [key]: {
            activeTabId: 'chat',
            tabs: [
              makeTab({
                id: 'chat',
                interfaceMode: 'auto',
                providerType: 'claude',
                messages: [],
              }),
            ],
          },
        },
      });

      await useChatStore.getState().sendMessage('Repeat that demo');
      for (let i = 0; i < 10; i += 1) {
        await Promise.resolve();
      }

      // Writing to the dead terminal would be silently dropped by the PTY
      // manager — the prompt must ride along as the CLI's initial argument
      // on a fresh launch instead.
      expect(terminalWriteMock).not.toHaveBeenCalled();
      expect(sendMessageMock).not.toHaveBeenCalled();
      expect(claudeTerminalLaunchMock).toHaveBeenCalledWith(
        expect.objectContaining({
          projectId: 'project',
          worktreeId: 'worktree',
          chatId: 'chat',
          initialPrompt: 'Repeat that demo',
          interfaceMode: 'auto',
        }),
      );
      // Flush any debounced saves so they cannot leak into later tests that
      // assert no saves were scheduled for this worktree.
      await jest.advanceTimersByTimeAsync(600);
    } finally {
      __resetClaudeTerminalStoreForTests();
      claudeTerminalGetStateMock.mockReset();
    }
  });

