  it.each(['rejected', 'transport failed'])(
    'preserves the OpenCode proposal when guarded approval is %s',
    async (failure) => {
      const { useChatStore } = loadChatStore();
      const send = jest.fn().mockResolvedValue(undefined);
      activityPlansUpdateMock.mockResolvedValue(null);
      chatCommandMock.mockImplementation((request) => {
        if (request.command.type === 'chat.send_message') {
          if (failure === 'transport failed')
            return Promise.reject(new Error('Write failed'));
          return Promise.resolve({
            commandId: request.commandId,
            revision: 1,
            outcome: 'rejected',
          });
        }
        return Promise.resolve({
          commandId: request.commandId,
          revision: 1,
          outcome: 'applied',
        });
      });
      const proposal = makeTab({
        id: 'chat',
        planMode: true,
        providerType: 'opencode',
        model: 'opencode:fixture%2Fmodel',
        pendingPlanExit: { plan: 'Implement the parser', source: 'opencode' },
        pendingPlanExitRequestId: 'opencode-review',
        trackedPlanId: 'opencode-plan',
        trackedPlanSource: 'opencode',
        trackedPlanReviewStatus: 'pending',
        latestRevisionNumber: 2,
      });
      useChatStore.setState({
        selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
        worktreeChats: {
          'project/worktree': { activeTabId: 'chat', tabs: [proposal] },
        },
        sendMessage: send,
      });

      void useChatStore.getState().approvePlanExit('');
      await jest.advanceTimersByTimeAsync(0);

      expect(send).not.toHaveBeenCalled();
      expect(activityPlansUpdateMock).not.toHaveBeenCalled();
      expect(
        useChatStore.getState().worktreeChats['project/worktree']?.tabs[0],
      ).toEqual(proposal);
      expect(
        useChatStore.getState().chatStateNotices['project/worktree'],
      ).toMatchObject({
        kind: 'command_failed',
      });
    },
  );

