  it('shows an info toast when an inactive chat finishes and becomes unread', async () => {
    const {
      chatStore: { useChatStore },
      githubStore: { useGitHubStore },
    } = loadChatAndGitHubStores();
    const osNotifications = enableChatOsNotifications();

    useChatStore.setState({
      selectedWorktree: {
        projectId: 'projB',
        worktreeId: 'wtB',
      },
      worktreeChats: {
        'projA/wtA': {
          activeTabId: 'chatA',
          tabs: [
            makeTab({
              id: 'chatA',
              title: 'Build fix',
              messages: [
                {
                  id: 'assistant-preview',
                  role: 'assistant',
                  blocks: [
                    {
                      type: 'text',
                      text: 'Agent finished the build fix.\nReady for review.',
                    },
                  ],
                  timestamp: Date.now(),
                },
              ],
            }),
          ],
        },
        'projB/wtB': {
          activeTabId: 'chatB',
          tabs: [makeTab({ id: 'chatB', title: 'Visible chat' })],
        },
      },
    });

    useChatStore.getState().handleChatEvent({
      projectId: 'projA',
      worktreeId: 'wtA',
      chatId: 'chatA',
      data: { type: 'result', is_error: false, result: 'Done' },
    });

    expect(osNotifications).not.toHaveBeenCalled();
    expect(useGitHubStore.getState().toasts).toHaveLength(0);

    await jest.advanceTimersByTimeAsync(3000);

    expect(osNotifications).toHaveBeenCalledTimes(1);
    const toasts = useGitHubStore.getState().toasts;
    expect(toasts).toHaveLength(1);
    const toast = toasts[0];
    if (!toast) {
      throw new Error('Expected unread chat toast');
    }
    expect(toast.type).toBe('info');
    // The toast headline names the worktree, so the message leaves the
    // branch out; the native banner has no such headline and keeps it.
    expect(toast.message).toBe(
      'Build fix: Agent finished the build fix. Ready for review.',
    );
    expect(osNotifications).toHaveBeenCalledWith(
      expect.objectContaining({
        body: 'wtA: Build fix: Agent finished the build fix. Ready for review.',
      }),
    );
    expect(toast.meta).toMatchObject({
      category: 'Chat',
      projectId: 'projA',
      worktreeId: 'wtA',
      chatId: 'chatA',
    });

    useChatStore.getState().handleChatEvent({
      projectId: 'projA',
      worktreeId: 'wtA',
      chatId: 'chatA',
      data: { type: 'result', is_error: false, result: 'Done again' },
    });

    expect(osNotifications).toHaveBeenCalledTimes(1);
    expect(useGitHubStore.getState().toasts).toHaveLength(1);
    await jest.advanceTimersByTimeAsync(3000);
    expect(osNotifications).toHaveBeenCalledTimes(2);

    useGitHubStore.getState().dismissToast(toast.id);
    const dismissedTab =
      useChatStore.getState().worktreeChats['projA/wtA']?.tabs[0];
    expect(dismissedTab?.unread).toBe(true);
    expect(dismissedTab?.attentionDismissedAt).toBeUndefined();
    expect(useGitHubStore.getState().toasts).toHaveLength(0);
    expect(useGitHubStore.getState().notifications).toHaveLength(0);

    useChatStore.getState().handleChatEvent({
      projectId: 'projA',
      worktreeId: 'wtA',
      chatId: 'chatA',
      data: { type: 'result', is_error: false, result: 'Done after dismiss' },
    });

    expect(osNotifications).toHaveBeenCalledTimes(2);
    expect(useGitHubStore.getState().toasts).toHaveLength(0);
    await jest.advanceTimersByTimeAsync(3000);
    expect(osNotifications).toHaveBeenCalledTimes(3);
    expect(useGitHubStore.getState().toasts).toHaveLength(0);
    expect(
      useChatStore.getState().worktreeChats['projA/wtA']?.tabs[0]?.unread,
    ).toBe(true);
  });

  it('shows an info toast when a cowork chat in another work entry finishes', async () => {
    const {
      chatStore: { useChatStore },
      githubStore: { useGitHubStore },
      navigationStore: { useNavigationStore },
    } = loadChatAndGitHubStores();
    const coworkRegistry = jest.requireActual<typeof CoworkRegistryModule>(
      '../lib/cowork-registry',
    );
    coworkRegistry.registerCoworkWorkspaceIds(['ws']);
    const osNotifications = enableChatOsNotifications();

    useNavigationStore.setState({ activePage: 'chat' });
    useChatStore.setState({
      selectedWorktree: { projectId: 'ws', worktreeId: 'entry-b' },
      worktreeChats: {
        'ws/entry-a': {
          activeTabId: 'chatA',
          tabs: [
            makeTab({
              id: 'chatA',
              title: 'Weekly report',
              description: 'Q3 planning session',
              messages: [
                {
                  id: 'assistant-preview',
                  role: 'assistant',
                  blocks: [{ type: 'text', text: 'Report drafted.' }],
                  timestamp: Date.now(),
                },
              ],
            }),
          ],
        },
        'ws/entry-b': {
          activeTabId: 'chatB',
          tabs: [makeTab({ id: 'chatB', title: 'Visible chat' })],
        },
      },
    });

    useChatStore.getState().handleChatEvent({
      projectId: 'ws',
      worktreeId: 'entry-a',
      chatId: 'chatA',
      data: { type: 'result', is_error: false, result: 'Done' },
    });

    // The completed chat is marked unread immediately; the Claude toast is
    // delivered after the short re-check delay.
    expect(
      useChatStore.getState().worktreeChats['ws/entry-a']?.tabs[0]?.unread,
    ).toBe(true);
    await jest.advanceTimersByTimeAsync(3000);

    expect(osNotifications).toHaveBeenCalledTimes(1);
    const toasts = useGitHubStore.getState().toasts;
    expect(toasts).toHaveLength(1);
    expect(toasts[0]?.type).toBe('info');
    // The headline names the work entry, so the message is the reply alone.
    expect(toasts[0]?.message).toBe('Report drafted.');
    expect(toasts[0]?.meta).toMatchObject({
      category: 'Chat',
      projectId: 'ws',
      worktreeId: 'entry-a',
      chatId: 'chatA',
    });

    // A result for the entry the user is actively viewing must NOT toast.
    useChatStore.getState().handleChatEvent({
      projectId: 'ws',
      worktreeId: 'entry-b',
      chatId: 'chatB',
      data: { type: 'result', is_error: false, result: 'Done' },
    });
    await jest.advanceTimersByTimeAsync(3000);
    expect(useGitHubStore.getState().toasts).toHaveLength(1);
    expect(
      useChatStore.getState().worktreeChats['ws/entry-b']?.tabs[0]?.unread,
    ).toBeFalsy();
  });

