  it('shares one getResolvedDefault call across concurrent fetchApprovalDefault callers', async () => {
    const { useChatStore } = loadChatStore();
    let resolveLookup:
      | ((mode: DesktopSharedTypes.ApprovalMode) => void)
      | undefined;
    getResolvedDefaultMock.mockReset();
    getResolvedDefaultMock.mockImplementation(
      () =>
        new Promise((resolve) => {
          resolveLookup = resolve;
        }),
    );

    const first = useChatStore.getState().fetchApprovalDefault('project');
    const second = useChatStore.getState().fetchApprovalDefault('project');

    expect(getResolvedDefaultMock).toHaveBeenCalledTimes(1);

    resolveLookup?.('full-access');
    const [firstResult, secondResult] = await Promise.all([first, second]);

    expect(firstResult).toBe('full-access');
    expect(secondResult).toBe('full-access');
    expect(getResolvedDefaultMock).toHaveBeenCalledTimes(1);

    // A subsequent call after the in-flight lookup settled issues a fresh
    // IPC round trip rather than replaying the stale in-flight promise.
    getResolvedDefaultMock.mockResolvedValue('ask');
    await useChatStore.getState().fetchApprovalDefault('project');
    expect(getResolvedDefaultMock).toHaveBeenCalledTimes(2);
  });

  it('joins a superseding force-fresh lookup through subsequent invalidation', async () => {
    const { useChatStore } = loadChatStore();
    const { invalidateApprovalDefaults } = jest.requireActual<
      typeof ApprovalDefaultsModule
    >('../stores/chat/approval-defaults');
    const resolveLookups: Array<
      (mode: DesktopSharedTypes.ApprovalMode) => void
    > = [];
    getResolvedDefaultMock.mockReset();
    getResolvedDefaultMock.mockImplementation(
      () =>
        new Promise((resolve) => {
          resolveLookups.push(resolve);
        }),
    );

    const initialLookup = useChatStore
      .getState()
      .fetchApprovalDefault('project', 'worktree');
    invalidateApprovalDefaults();
    useChatStore.setState({ approvalDefaultsCache: {} });
    const creationLookup = useChatStore
      .getState()
      .fetchApprovalDefault('project', 'worktree', { forceFresh: true });
    invalidateApprovalDefaults();
    useChatStore.setState({ approvalDefaultsCache: {} });
    const subsequentRegularLookup = useChatStore
      .getState()
      .fetchApprovalDefault('project', 'worktree');

    expect(getResolvedDefaultMock).toHaveBeenCalledTimes(2);
    resolveLookups[0]?.('full-access');

    let initialSettled = false;
    void initialLookup.then(() => {
      initialSettled = true;
    });
    await Promise.resolve();
    expect(initialSettled).toBe(false);

    resolveLookups[1]?.('auto');
    await Promise.resolve();
    await Promise.resolve();
    expect(getResolvedDefaultMock).toHaveBeenCalledTimes(3);

    resolveLookups[2]?.('full-access');
    await expect(initialLookup).resolves.toBe('full-access');
    await expect(creationLookup).resolves.toBe('full-access');
    await expect(subsequentRegularLookup).resolves.toBe('full-access');
    expect(useChatStore.getState().approvalDefaultsCache.project).toBe(
      'full-access',
    );
  });

