  it('joins the current default lookup when an invalidated creation-boundary lookup rejects', async () => {
    const { useChatStore } = loadChatStore();
    const { invalidateApprovalDefaults } = jest.requireActual<
      typeof ApprovalDefaultsModule
    >('../stores/chat/approval-defaults');
    let rejectInitialLookup: ((error: Error) => void) | undefined;
    let resolveFreshLookup:
      | ((mode: DesktopSharedTypes.ApprovalMode) => void)
      | undefined;
    getResolvedDefaultMock
      .mockImplementationOnce(
        () =>
          new Promise((_, reject) => {
            rejectInitialLookup = reject;
          }),
      )
      .mockImplementationOnce(
        () =>
          new Promise((resolve) => {
            resolveFreshLookup = resolve;
          }),
      );
    useChatStore.setState({
      approvalDefaultsCache: { project: 'full-access' },
    });

    const invalidatedLookup = useChatStore
      .getState()
      .fetchApprovalDefault('project', 'worktree', { forceFresh: true });
    invalidateApprovalDefaults();
    useChatStore.setState({ approvalDefaultsCache: {} });
    const freshLookup = useChatStore
      .getState()
      .fetchApprovalDefault('project', 'worktree', { forceFresh: true });
    rejectInitialLookup?.(new Error('stale request failed'));
    resolveFreshLookup?.('auto');

    await expect(invalidatedLookup).resolves.toBe('auto');
    await expect(freshLookup).resolves.toBe('auto');
    expect(getResolvedDefaultMock).toHaveBeenCalledTimes(2);
    expect(useChatStore.getState().approvalDefaultsCache.project).toBe('auto');
  });

  it('starts a fresh default lookup when the in-flight generation is stale', async () => {
    const { useChatStore } = loadChatStore();
    const { invalidateApprovalDefaults } = jest.requireActual<
      typeof ApprovalDefaultsModule
    >('../stores/chat/approval-defaults');
    const resolveLookups: Array<
      (mode: DesktopSharedTypes.ApprovalMode) => void
    > = [];
    getResolvedDefaultMock.mockReset();
    getResolvedDefaultMock.mockImplementation(
      () =>
        new Promise((resolve) => {
          resolveLookups.push(resolve);
        }),
    );

    const staleLookup = useChatStore.getState().fetchApprovalDefault('project');
    invalidateApprovalDefaults();
    useChatStore.setState({ approvalDefaultsCache: {} });
    const freshLookup = useChatStore.getState().fetchApprovalDefault('project');

    expect(getResolvedDefaultMock).toHaveBeenCalledTimes(2);
    resolveLookups[0]?.('full-access');
    await expect(staleLookup).resolves.toBe('ask');

    const concurrentFreshLookup = useChatStore
      .getState()
      .fetchApprovalDefault('project');
    expect(concurrentFreshLookup).toBe(freshLookup);
    expect(getResolvedDefaultMock).toHaveBeenCalledTimes(2);

    resolveLookups[1]?.('auto');
    await expect(freshLookup).resolves.toBe('auto');
    await expect(concurrentFreshLookup).resolves.toBe('auto');
    expect(useChatStore.getState().approvalDefaultsCache.project).toBe('auto');
  });

