  it('waits for an in-flight tab load before marking the selected worktree as ready', async () => {
    const { useChatStore } = loadChatStore();

    const loadTabsDeferred: {
      resolve?: (value: ChatTabsFile) => void;
    } = {};
    loadTabsMock.mockImplementation(
      () =>
        new Promise<ChatTabsFile>((resolve) => {
          loadTabsDeferred.resolve = resolve;
        }),
    );

    useChatStore.getState().selectWorktree('proj', 'wt');
    await Promise.resolve();

    const readyPromise = useChatStore
      .getState()
      .ensureSelectedWorktreeTabsLoaded();

    let resolved = false;
    void readyPromise.then(() => {
      resolved = true;
    });

    await Promise.resolve();
    await Promise.resolve();
    expect(loadTabsMock).toHaveBeenCalledTimes(1);
    expect(resolved).toBe(false);

    const resolveTabs = loadTabsDeferred.resolve;
    if (!resolveTabs) {
      throw new Error('Expected loadTabs resolver to be set');
    }

    resolveTabs({
      version: 1,
      activeTabId: 'chat-1',
      tabs: [
        {
          id: 'chat-1',
          title: 'Restored Chat',
          messages: [],
          createdAt: '2026-03-19T00:00:00.000Z',
          planMode: false,
          thinkingLevel: 'high',
          model: 'claude-sonnet-4-6',
          providerType: 'claude',
        },
      ],
    });

    await Promise.resolve();
    await Promise.resolve();
    await jest.advanceTimersByTimeAsync(50);

    await expect(readyPromise).resolves.toBe(true);
    expect(useChatStore.getState().worktreeChats['proj/wt']?.activeTabId).toBe(
      'chat-1',
    );
  });

