  it('detects a stale Claude resume and preserves the dropped message', async () => {
    const { useChatStore } = loadChatStore();

    useChatStore.setState({
      selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
      worktreeChats: {
        'project/worktree': {
          activeTabId: 'chat',
          tabs: [
            makeTab({
              sdkSessionId: 'stale-session',
              claudeForkSessionOnNextSend: true,
            }),
          ],
        },
      },
    });

    await useChatStore.getState().sendMessage('Retry the failed turn');

    useChatStore.getState().handleChatEvent({
      projectId: 'project',
      worktreeId: 'worktree',
      chatId: 'chat',
      data: { type: 'result', is_error: false, result: 'Session ended' },
    });

    const tab =
      useChatStore.getState().worktreeChats['project/worktree']?.tabs[0];
    const lastUserMessage = [...(tab?.messages ?? [])]
      .reverse()
      .find((message) => message.role === 'user');

    expect(tab?.staleSessionDetected).toEqual({
      droppedMessageText: 'Retry the failed turn',
    });
    expect(tab?.sdkSessionId).toBeUndefined();
    expect(tab?.claudeForkSessionOnNextSend).toBeUndefined();
    expect(tab?.lastTurnWasResumeAttempt).toBeUndefined();
    expect(tab?.readOnly).toBe(true);
    expect(lastUserMessage?.blocks).toContainEqual({
      type: 'text',
      text: 'Retry the failed turn',
    });
  });

