  it.each(['after', 'before'] as const)(
    'does not dispatch a stopped send when a new send starts %s its approval lookup completes',
    async (newSendTiming) => {
      const { useChatStore } = loadChatStore();
      let releaseLookup:
        | ((mode: DesktopSharedTypes.ApprovalMode) => void)
        | undefined;
      getResolvedDefaultMock.mockImplementationOnce(
        () =>
          new Promise((resolve) => {
            releaseLookup = resolve;
          }),
      );
      const target = {
        projectId: 'project',
        worktreeId: 'worktree',
        chatId: 'chat',
      };
      const rejected = jest.fn();
      const preDispatchRejected = jest.fn();
      const accepted = jest.fn();
      useChatStore.setState({
        selectedWorktree: { projectId: 'another', worktreeId: 'worktree' },
        approvalDefaultsCache: {},
        worktreeChats: {
          'project/worktree': { activeTabId: 'chat', tabs: [makeTab()] },
        },
      });
      const send = useChatStore
        .getState()
        .sendMessage('Stopped before dispatch', undefined, target, undefined, {
          onDispatchRejected: rejected,
          onPreDispatchRejected: preDispatchRejected,
          onDispatchAccepted: accepted,
        });
      await flushChatStoreAsyncWork();
      expect(releaseLookup).toBeDefined();
      await useChatStore.getState().cancelSession(target);
      useChatStore.getState().handleChatEvent({
        ...target,
        data: { type: 'result', is_error: false, result: 'Cancelled' },
      });
      if (newSendTiming === 'before') {
        useChatStore.setState({ approvalDefaultsCache: { project: 'ask' } });
        await useChatStore
          .getState()
          .sendMessage('A new independent send', undefined, target);
      }
      releaseLookup?.('ask');
      await send;
      expect(rejected).toHaveBeenCalledTimes(1);
      expect(preDispatchRejected).toHaveBeenCalledTimes(1);
      expect(accepted).not.toHaveBeenCalled();
      expect(sendMessageMock).toHaveBeenCalledTimes(
        newSendTiming === 'before' ? 1 : 0,
      );
      expect(cancelChatMock).toHaveBeenCalledWith(target);
      if (newSendTiming === 'after') {
        expect(
          useChatStore.getState().worktreeChats['project/worktree']?.tabs[0]
            ?.status,
        ).toBe('idle');
        await useChatStore
          .getState()
          .sendMessage('A new independent send', undefined, target);
      }
      expect(sendMessageMock).toHaveBeenCalledTimes(1);
      expect(sendMessageMock).toHaveBeenCalledWith(
        expect.objectContaining({ ...target, text: 'A new independent send' }),
      );
    },
  );

