  it('renders chat-send guard rejections verbatim without an Error: prefix or wrapper', async () => {
    const { useChatStore } = loadChatStore();
    const guardText =
      'Canopy is already running 4 chat turns. Wait for one to finish before starting another.';
    sendMessageMock.mockRejectedValueOnce(new Error(guardText));

    useChatStore.setState({
      selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
      worktreeChats: {
        'project/worktree': {
          activeTabId: 'chat',
          tabs: [makeTab()],
        },
      },
    });

    await useChatStore.getState().sendMessage('Send under guard');

    const tab =
      useChatStore.getState().worktreeChats['project/worktree']?.tabs[0];
    expect(tab?.status).toBe('error');
    expect(tab?.error).toBe(guardText);
    expect(tab?.error).not.toMatch(/^Error:/);
    const visibleErrorMessage = tab?.messages[tab.messages.length - 1];
    expect(visibleErrorMessage).toMatchObject({
      role: 'system',
      blocks: [{ type: 'text', text: guardText }],
    });
    const timerMessage = tab?.messages.find((message) =>
      message.blocks.some((block) => block.type === 'turn_timer'),
    );
    const timerBlock = timerMessage?.blocks.find(
      (block) => block.type === 'turn_timer',
    );
    expect(timerBlock?.type).toBe('turn_timer');
    expect(
      timerBlock?.type === 'turn_timer'
        ? typeof timerBlock.completedAt
        : 'missing',
    ).toBe('number');
  });

