  describe('guarded starter-tab replacement', () => {
    const entryKey = `${STANDALONE_CHAT_PROJECT_ID}/entry-send`;
    const emptyParagraph = [
      { type: 'paragraph' as const, children: [{ text: '' }] },
    ];
    const savedDraft = [
      { type: 'paragraph' as const, children: [{ text: 'keep me' }] },
    ];
    const savedFileReferenceDraft: ChatTabUtils.PristineChatTabComposerState['tabDrafts'][string] =
      [
        {
          type: 'paragraph' as const,
          children: [
            { text: '' },
            {
              type: 'file-reference' as const,
              displayPath: 'src/a.ts',
              absolutePath: '/repo/src/a.ts',
              children: [{ text: '' }],
            },
            { text: '' },
          ],
        },
      ];
    const stagedSelection = {
      id: 'selection-1',
      projectId: STANDALONE_CHAT_PROJECT_ID,
      worktreeId: 'entry-send',
      absolutePath: '/repo/example.ts',
      displayPath: 'example.ts',
      startLine: 1,
      startColumn: 1,
      endLine: 1,
      endColumn: 6,
      text: 'alpha',
      capturedDirty: false,
    };

    function seedStarter(
      useChatStore: ReturnType<typeof loadChatStore>['useChatStore'],
      tabOverrides: Partial<ChatStoreModule.ChatTab> = {},
      composer: Partial<ChatTabUtils.PristineChatTabComposerState> = {},
    ): void {
      useChatStore.setState({
        worktreeChats: {
          [entryKey]: {
            activeTabId: 'starter',
            tabs: [makeTab({ id: 'starter', ...tabOverrides })],
          },
        },
        tabDrafts: {},
        composerTextPresent: {},
        pendingEditorSelections: {},
        ...composer,
      });
    }

    function createHomeChat(
      useChatStore: ReturnType<typeof loadChatStore>['useChatStore'],
      replaceActiveEmpty = true,
    ): void {
      useChatStore.getState().createTab({
        projectId: STANDALONE_CHAT_PROJECT_ID,
        worktreeId: 'entry-send',
        id: 'home-chat',
        replaceActiveEmpty,
      });
    }

    it.each([
      ['no composer state', {}],
      [
        'an untouched empty saved paragraph',
        { tabDrafts: { starter: emptyParagraph } },
      ],
    ])('replaces a pristine active starter with %s', (_label, composer) => {
      const { useChatStore } = loadChatStore();
      seedStarter(useChatStore, {}, composer);

      createHomeChat(useChatStore);

      const state = useChatStore.getState().worktreeChats[entryKey];
      expect(state?.activeTabId).toBe('home-chat');
      expect(state?.tabs.map((tab) => tab.id)).toEqual(['home-chat']);
    });

    it.each<
      [
        string,
        Partial<ChatStoreModule.ChatTab>,
        Partial<ChatTabUtils.PristineChatTabComposerState>,
      ]
    >([
      ['a saved text draft', {}, { tabDrafts: { starter: savedDraft } }],
      [
        'a saved file reference',
        {},
        { tabDrafts: { starter: savedFileReferenceDraft } },
      ],
      ['live composer text', {}, { composerTextPresent: { starter: true } }],
      [
        'pending attachments',
        {
          pendingAttachments: [
            { filename: 'notes.md', absolutePath: '/tmp/notes.md' },
          ],
        },
        {},
      ],
      [
        'a pending revert summary',
        { pendingRevertAttachmentPath: '/tmp/revert.md' },
        {},
      ],
      [
        'a scheduled-send draft',
        { scheduledSendDraft: { runAt: '2099-01-01T09:00:00.000Z' } },
        {},
      ],
      [
        'staged editor selections',
        {},
        { pendingEditorSelections: { starter: [stagedSelection] } },
      ],
      [
        'loaded messages',
        {
          messages: [
            {
              id: 'm1',
              role: 'user',
              blocks: [{ type: 'text', text: 'hello' }],
              timestamp: Date.parse('2026-03-19T00:00:00.000Z'),
            },
          ],
        },
        {},
      ],
      [
        'a persisted transcript without loaded messages',
        {
          transcript: {
            format: 'complete-message-jsonl-v1',
            committedMessageCount: 2,
            committedByteLength: 200,
            transcriptRevision: 1,
            hasActiveSidecar: false,
            messageCount: 2,
          },
        },
        {},
      ],
      [
        'queued messages',
        {
          queuedMessages: [
            {
              text: 'later',
            },
          ],
        },
        {},
      ],
      ['a running turn', { status: 'streaming' }, {}],
      ['a pending plan exit', { pendingPlanExit: {} }, {}],
    ])(
      'keeps a starter holding %s and opens beside it',
      async (_label, tab, composer) => {
        const { useChatStore } = loadChatStore();
        seedStarter(useChatStore, tab, composer);
        useChatStore.setState({
          chatStateSync: { [entryKey]: { phase: 'live', revision: 1 } },
        });
        chatCommandMock.mockClear();
        const before = useChatStore.getState();
        const starterBefore = before.worktreeChats[entryKey]?.tabs[0];

        createHomeChat(useChatStore);

        const after = useChatStore.getState();
        const state = after.worktreeChats[entryKey];
        expect(state?.activeTabId).toBe('home-chat');
        expect(state?.tabs.map((candidate) => candidate.id)).toEqual([
          'starter',
          'home-chat',
        ]);
        expect(state?.tabs[0]).toBe(starterBefore);
        expect(after.tabDrafts.starter).toBe(before.tabDrafts.starter);
        expect(after.composerTextPresent.starter).toBe(
          before.composerTextPresent.starter,
        );
        expect(after.pendingEditorSelections.starter).toBe(
          before.pendingEditorSelections.starter,
        );
        await flushChatStoreAsyncWork();
        expect(
          chatCommandMock.mock.calls.some(
            ([request]) => request.command.type === 'chat.close_tab',
          ),
        ).toBe(false);
      },
    );

    it('appends beside a pristine starter when replacement is not requested', () => {
      const { useChatStore } = loadChatStore();
      seedStarter(useChatStore);

      createHomeChat(useChatStore, false);

      expect(
        useChatStore
          .getState()
          .worktreeChats[entryKey]?.tabs.map((tab) => tab.id),
      ).toEqual(['starter', 'home-chat']);
    });

    it('keeps an active file tab', () => {
      const { useChatStore } = loadChatStore();
      useChatStore.setState({
        worktreeChats: {
          [entryKey]: {
            activeTabId: 'file-tab',
            tabs: [makeTab({ id: 'file-tab', title: 'a.ts', kind: 'file' })],
          },
        },
      });

      createHomeChat(useChatStore);

      expect(
        useChatStore
          .getState()
          .worktreeChats[entryKey]?.tabs.map((tab) => tab.id),
      ).toEqual(['file-tab', 'home-chat']);
    });

    it('replaces only the active target and leaves other tabs and worktrees alone', () => {
      const { useChatStore } = loadChatStore();
      const otherKey = `${STANDALONE_CHAT_PROJECT_ID}/entry-other`;
      const inactive = makeTab({ id: 'inactive-empty' });
      const otherStarter = makeTab({ id: 'other-starter' });
      useChatStore.setState({
        worktreeChats: {
          [entryKey]: {
            activeTabId: 'starter',
            tabs: [inactive, makeTab({ id: 'starter' })],
          },
          [otherKey]: { activeTabId: 'other-starter', tabs: [otherStarter] },
        },
      });

      createHomeChat(useChatStore);

      const state = useChatStore.getState();
      expect(state.worktreeChats[entryKey]?.tabs.map((tab) => tab.id)).toEqual([
        'inactive-empty',
        'home-chat',
      ]);
      expect(state.worktreeChats[entryKey]?.tabs[0]).toBe(inactive);
      expect(state.worktreeChats[otherKey]?.tabs).toEqual([otherStarter]);
    });

    it.each([
      ['a replaced pristine starter', {}, false],
      ['a kept draft starter', { tabDrafts: { starter: savedDraft } }, true],
    ])(
      'leaves a usable chat after rolling back a failed first send over %s',
      async (_label, composer, keepsStarter) => {
        const { useChatStore } = loadChatStore();
        loadTabsMock.mockResolvedValue({
          version: 1,
          activeTabId: 'starter',
          tabs: [
            {
              id: 'starter',
              title: 'New Chat',
              createdAt: '2026-03-19T00:00:00.000Z',
              messages: [],
            },
          ],
        });
        await useChatStore
          .getState()
          .loadTabsForTarget(STANDALONE_CHAT_PROJECT_ID, 'entry-send');
        useChatStore.setState({
          tabDrafts: {},
          composerTextPresent: {},
          pendingEditorSelections: {},
          ...composer,
        });

        createHomeChat(useChatStore);
        // The send failed: the orchestration force-closes the new chat.
        useChatStore.getState().closeTab('home-chat', {
          projectId: STANDALONE_CHAT_PROJECT_ID,
          worktreeId: 'entry-send',
          force: true,
        });

        const state = useChatStore.getState();
        const entry = state.worktreeChats[entryKey];
        expect(entry?.tabs).toHaveLength(1);
        expect(entry?.tabs.some((tab) => tab.id === 'home-chat')).toBe(false);
        expect(entry?.activeTabId).toBe(entry?.tabs[0]?.id);
        expect(entry?.tabs[0]?.id === 'starter').toBe(keepsStarter);
        if (keepsStarter) {
          expect(state.tabDrafts.starter).toEqual(savedDraft);
        }
      },
    );

    it.each([
      ['Home', false],
      ['command', true],
    ])(
      '%s orchestration rolls back a rejected send through the real tab lifecycle',
      async (_label, commandSend) => {
        // Run both production stores together. Only transport and the rejected
        // provider dispatch are faked; replacement and last-tab recovery are real.
        for (const keepsDraft of [false, true]) {
          const { useChatStore } = loadChatStore();
          const { useStandaloneChatStore } = jest.requireActual<
            typeof StandaloneChatStoreModule
          >('../stores/standaloneChatStore');
          const entryMeta: DesktopSharedTypes.CoworkWorkEntryMeta = {
            id: 'entry-send',
            title: 'Entry',
            createdAt: '2026-03-19T00:00:00.000Z',
            chatCount: 1,
          };
          const createEntry = jest.fn().mockResolvedValue({
            entry: entryMeta,
            reusedExistingEmpty: true,
          });
          const deleteEntry = jest.fn();
          Object.defineProperty(window.api, 'workEntries', {
            value: {
              create: createEntry,
              list: jest.fn().mockResolvedValue({ entries: [entryMeta] }),
              delete: deleteEntry,
            },
          });
          loadTabsMock.mockResolvedValue({
            version: 1,
            activeTabId: 'starter',
            tabs: [
              {
                id: 'starter',
                title: 'New Chat',
                createdAt: entryMeta.createdAt,
                messages: [],
              },
            ],
          });
          await useChatStore
            .getState()
            .loadTabsForTarget(STANDALONE_CHAT_PROJECT_ID, 'entry-send');
          useChatStore.setState({
            selectedWorktree: {
              projectId: STANDALONE_CHAT_PROJECT_ID,
              worktreeId: 'entry-send',
            },
            tabDrafts: keepsDraft ? { starter: savedDraft } : {},
          });
          useStandaloneChatStore.setState({
            initialized: true,
            activeChatProjectId: STANDALONE_CHAT_PROJECT_ID,
            activeWorkEntryId: 'entry-send',
            workEntries: [entryMeta],
          });
          const send = jest
            .spyOn(useChatStore.getState(), 'sendMessage')
            .mockImplementation(() => {
              const entry = useChatStore.getState().worktreeChats[entryKey];
              expect(entry?.tabs.map((tab) => tab.id)).toEqual(
                keepsDraft
                  ? ['starter', 'failed-home-chat']
                  : ['failed-home-chat'],
              );
              return Promise.reject(new Error('initial dispatch rejected'));
            });
          const request = {
            chatId: 'failed-home-chat',
            message: 'first prompt',
          };
          try {
            await expect(
              commandSend
                ? useStandaloneChatStore
                    .getState()
                    .createWorkEntryChatWithMessage(request)
                : useStandaloneChatStore
                    .getState()
                    .createStandaloneChatWithMessage({
                      ...request,
                      chatProjectId: STANDALONE_CHAT_PROJECT_ID,
                    }),
            ).rejects.toThrow('initial dispatch rejected');
            expect(send).toHaveBeenCalledTimes(1);
            expect(createEntry).toHaveBeenCalledTimes(1);
            expect(deleteEntry).not.toHaveBeenCalled();
            const state = useChatStore.getState();
            const entry = state.worktreeChats[entryKey];
            expect(entry?.tabs).toHaveLength(1);
            expect(entry?.activeTabId).toBe(entry?.tabs[0]?.id);
            expect(entry?.activeTabId).not.toBe('failed-home-chat');
            expect(entry?.tabs[0]?.id === 'starter').toBe(keepsDraft);
            expect(state.selectedWorktree?.worktreeId).toBe('entry-send');
            expect(useStandaloneChatStore.getState().activeWorkEntryId).toBe(
              'entry-send',
            );
            expect(useStandaloneChatStore.getState().workEntries).toEqual([
              entryMeta,
            ]);
            if (keepsDraft) expect(state.tabDrafts.starter).toEqual(savedDraft);
          } finally {
            send.mockRestore();
          }
        }
      },
    );

    it('requests a canonical discard only for a replaced pristine starter', async () => {
      const { useChatStore } = loadChatStore();
      seedStarter(useChatStore, {}, { tabDrafts: { starter: savedDraft } });
      useChatStore.setState({
        chatStateSync: { [entryKey]: { phase: 'live', revision: 1 } },
      });
      chatCommandMock.mockClear();

      createHomeChat(useChatStore);
      await flushChatStoreAsyncWork();

      expect(
        chatCommandMock.mock.calls.some(
          ([request]) => request.command.type === 'chat.close_tab',
        ),
      ).toBe(false);

      seedStarter(useChatStore);
      useChatStore.setState({
        chatStateSync: { [entryKey]: { phase: 'live', revision: 1 } },
      });
      chatCommandMock.mockClear();

      createHomeChat(useChatStore);
      await flushChatStoreAsyncWork();

      expect(
        chatCommandMock.mock.calls.some(
          ([request]) =>
            request.command.type === 'chat.close_tab' &&
            request.command.tabId === 'starter' &&
            request.command.mode === 'discard_empty',
        ),
      ).toBe(true);
    });
  });

