    forkOpenWorktreeTabsMock.mockReset().mockResolvedValue({
      tabBindings: {},
      selectedTabApprovalMode: 'ask',
    });
    adhocMigrateTabsMock.mockReset().mockResolvedValue({ migratedTabIds: [] });
    loadTabsMock.mockReset().mockResolvedValue({
      version: 1,
      tabs: [],
      activeTabId: '',
    });
    activeSessionsMock.mockReset().mockResolvedValue({ activeChatIds: [] });
    getChatQueueSnapshotMock.mockReset().mockResolvedValue([]);
    cancelQueuedHookChatMock.mockReset().mockResolvedValue({ cancelled: true });
    forceQueuedHookChatMock.mockReset().mockResolvedValue({ forced: true });
