  it('shows the hook banner on a queued hook placeholder without adding transcript messages', () => {
    const { useChatStore } = loadChatStore();
    const { toActiveTranscriptView } = jest.requireActual<typeof ChatViewTypes>(
      '../components/chat/types',
    );
    const { getOnlyQueuedHookPlaceholderQueueId } = jest.requireActual<
      typeof ChatTabUtils
    >('../stores/chat/tab-utils');
    useChatStore.setState({
      worktreeChats: {
        'project/worktree': {
          activeTabId: 'existing',
          tabs: [makeTab({ id: 'existing', title: 'Existing tab' })],
        },
      },
    });

    useChatStore.getState().handleHookTabStarted({
      projectId: 'project',
      worktreeId: 'worktree',
      chatId: 'hook-chat',
      activateTab: true,
      tab: {
        id: 'hook-chat',
        title: 'Review failures',
        createdAt: '2026-07-19T00:00:00.000Z',
        messages: [],
      },
      queuedMessage: {
        queueId: 'hook-queue-1',
        text: 'Review failures',
        reason: 'Waiting for active chat sessions to finish.',
        hookInfo: { triggerName: 'pr:checks:fail', timestamp: 1_000 },
      },
    });

    const placeholder = useChatStore
      .getState()
      .worktreeChats[
        'project/worktree'
      ]?.tabs.find((tab) => tab.id === 'hook-chat');
    if (!placeholder) throw new Error('Expected queued hook placeholder');
    // The banner is presentation-only: the placeholder keeps no transcript
    // messages, so lone-placeholder detection (close/cancel, busy state) holds.
    expect(placeholder.messages).toEqual([]);
    expect(getOnlyQueuedHookPlaceholderQueueId(placeholder)).toBe(
      'hook-queue-1',
    );
    const view = toActiveTranscriptView(placeholder);
    expect(view.messages).toEqual([
      expect.objectContaining({
        role: 'system',
        timestamp: 1_000,
        blocks: [
          {
            type: 'hook_info',
            triggerName: 'pr:checks:fail',
            timestamp: 1_000,
          },
        ],
      }),
    ]);
    // `useShallow` selectors compare by reference; the projection is stable.
    expect(toActiveTranscriptView(placeholder).messages).toBe(view.messages);

    useChatStore.getState().handleHookTabStarted({
      projectId: 'project',
      worktreeId: 'worktree',
      chatId: 'hook-chat',
      activateTab: true,
      tab: {
        id: 'hook-chat',
        title: 'Review failures',
        createdAt: '2026-07-19T00:00:00.000Z',
        messages: [
          {
            id: 'hook-info',
            role: 'system',
            timestamp: 1_000,
            blocks: [
              {
                type: 'hook_info',
                triggerName: 'pr:checks:fail',
                timestamp: 1_000,
              },
            ],
          },
          {
            id: 'hook-user',
            role: 'user',
            timestamp: 2_000,
            blocks: [{ type: 'text', text: 'Review failures' }],
          },
        ],
      },
    });

    const started = useChatStore
      .getState()
      .worktreeChats[
        'project/worktree'
      ]?.tabs.find((tab) => tab.id === 'hook-chat');
    if (!started) throw new Error('Expected started hook chat');
    expect(started.queuedHookPlaceholder).toBeUndefined();
    expect(
      toActiveTranscriptView(started).messages.filter((message) =>
        message.blocks.some((block) => block.type === 'hook_info'),
      ),
    ).toHaveLength(1);
  });

