  it('does not overwrite a forked Codex tab session after the tab advances independently', async () => {
    const { useChatStore } = loadChatStore();
    let resolveFork: ((value: { forkedThreadId: string }) => void) | null =
      null;
    const forkCodexThreadMock = jest
      .fn<Promise<{ forkedThreadId: string }>, [unknown]>()
      .mockImplementation(
        () =>
          new Promise((resolve) => {
            resolveFork = resolve;
          }),
      );

    Object.defineProperty(window, 'api', {
      configurable: true,
      value: {
        ...window.api,
        chat: {
          ...window.api.chat,
          forkCodexThread: forkCodexThreadMock,
        },
      },
    });

    useChatStore.setState({
      selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
      worktreeChats: {
        'project/worktree': {
          activeTabId: 'chat',
          tabs: [
            makeTab({
              id: 'chat',
              title: 'Original',
              providerType: 'codex',
              model: 'gpt-6-sol',
              sdkSessionId: 'thread-source',
              messages: [
                {
                  id: 'msg-1',
                  role: 'user',
                  blocks: [{ type: 'text', text: 'Hello' }],
                  timestamp: 1,
                },
              ],
            }),
          ],
        },
      },
    });

    useChatStore.getState().forkTab('chat');

    const forkedTabId =
      useChatStore.getState().worktreeChats['project/worktree']?.activeTabId;
    if (!forkedTabId || forkedTabId === 'chat') {
      throw new Error('Expected forkTab to create a new active tab');
    }
    const finishFork = (): ((value: { forkedThreadId: string }) => void) => {
      if (!resolveFork) {
        throw new Error('Expected forkCodexThread to be requested');
      }
      return resolveFork;
    };

    useChatStore.setState((state) => {
      const current = state.worktreeChats['project/worktree'];
      if (!current) {
        return state;
      }
      return {
        worktreeChats: {
          ...state.worktreeChats,
          'project/worktree': {
            ...current,
            tabs: current.tabs.map((tab) =>
              tab.id === forkedTabId
                ? {
                    ...tab,
                    status: 'streaming',
                    messages: [
                      ...tab.messages,
                      {
                        id: 'msg-2',
                        role: 'user',
                        blocks: [{ type: 'text', text: 'Continue here' }],
                        timestamp: 2,
                      },
                    ],
                  }
                : tab,
            ),
          },
        },
      };
    });

    finishFork()({ forkedThreadId: 'thread-forked' });
    await Promise.resolve();
    await Promise.resolve();

    const forkedTab = useChatStore
      .getState()
      .worktreeChats[
        'project/worktree'
      ]?.tabs.find((tab) => tab.id === forkedTabId);

    expect(forkedTab?.sdkSessionId).toBeUndefined();
    expect(forkedTab?.messages).toHaveLength(2);
  });

