  it.each([
    {
      label: 'succeeds',
      initialMode: 'full-access' as const,
      requestedMode: 'ask' as const,
      finalMode: 'ask' as const,
      rejectTransition: false,
    },
    {
      label: 'rolls back',
      initialMode: 'ask' as const,
      requestedMode: 'full-access' as const,
      finalMode: 'ask' as const,
      rejectTransition: true,
    },
  ])(
    'waits for an approval-mode transition that $label before branching',
    async ({ initialMode, requestedMode, finalMode, rejectTransition }) => {
      const { useChatStore } = loadChatStore();
      const projectsStore = jest.requireActual<typeof ProjectsStoreModule>(
        '../stores/projectsStore',
      );
      const createWorktreeMock = jest.fn().mockResolvedValue({
        id: 'branched-worktree',
      });
      let resolveModeTransition: (() => void) | undefined;
      let rejectModeTransition: ((error: Error) => void) | undefined;

      setApprovalModeMock.mockImplementationOnce(
        () =>
          new Promise<void>((resolve, reject) => {
            resolveModeTransition = resolve;
            rejectModeTransition = reject;
          }),
      );
      projectsStore.useProjectsStore.setState({
        createWorktree: createWorktreeMock,
        refreshWorktreeDiffStatsVerified: jest.fn().mockResolvedValue(true),
      });
      useChatStore.setState({
        selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
        worktreeChats: {
          'project/worktree': {
            activeTabId: 'chat',
            tabs: [
              makeTab({
                id: 'chat',
                approvalMode: initialMode,
                messages: [
                  {
                    id: 'msg-1',
                    role: 'user',
                    blocks: [{ type: 'text', text: 'Branch after settling' }],
                    timestamp: 1,
                  },
                ],
              }),
            ],
          },
        },
      });

      const transition = useChatStore
        .getState()
        .setTabApprovalMode(undefined, requestedMode);
      const transitionOutcome = transition.then(
        () => 'resolved' as const,
        () => 'rejected' as const,
      );
      await Promise.resolve();
      await Promise.resolve();

      const branching = useChatStore.getState().branchTab('chat');
      await Promise.resolve();
      await Promise.resolve();
      expect(createWorktreeMock).not.toHaveBeenCalled();

      if (rejectTransition) {
        rejectModeTransition?.(new Error('Provider rejected mode change'));
      } else {
        resolveModeTransition?.();
      }
      expect(await transitionOutcome).toBe(
        rejectTransition ? 'rejected' : 'resolved',
      );
      expect((await branching).status).toBe('created');

      expect(
        useChatStore.getState().worktreeChats['project/branched-worktree']
          ?.tabs[0]?.approvalMode,
      ).toBe(finalMode);
    },
  );

  it('preserves one seeded branch tab and its divider anchor during first activation', async () => {
    const { useChatStore } = loadChatStore();
    const projectsStore = jest.requireActual<typeof ProjectsStoreModule>(
      '../stores/projectsStore',
    );
    type CreateWorktree = ReturnType<
      typeof projectsStore.useProjectsStore.getState
    >['createWorktree'];
    let destinationTabCountDuringRegistration = -1;
    let destinationTabCountDuringCanonicalActivation = -1;
    const createWorktreeMock = jest.fn<
      ReturnType<CreateWorktree>,
      Parameters<CreateWorktree>
    >(async (_projectId, options) => {
      options?.onRegistered?.({
        id: 'branched-worktree',
        branchName: 'branched-worktree',
        createdAt: '2026-09-15T12:00:00.000Z',
      });
      // Reproduce the eager destination hydration that can run as soon as the
      // new worktree row is registered, before createWorktree resolves back to
      // branchTab with the destination id.
      await useChatStore.getState().ensureWorktreeHasChatTab({
        projectId: 'project',
        worktreeId: 'branched-worktree',
      });
      destinationTabCountDuringRegistration =
        useChatStore.getState().worktreeChats['project/branched-worktree']?.tabs
          .length ?? 0;
      return { id: 'branched-worktree' };
    });

    projectsStore.useProjectsStore.setState({
      createWorktree: createWorktreeMock,
      refreshWorktreeDiffStatsVerified: jest.fn().mockResolvedValue(true),
    });
    forkOpenWorktreeTabsMock.mockImplementationOnce(async (request) => {
      const destinationKey = `${request.projectId}/${request.destinationWorktreeId}`;
      const stagedDestination =
        useChatStore.getState().worktreeChats[destinationKey];
      if (!stagedDestination) {
        throw new Error('Expected the branched tab to be staged locally');
      }
      // Reproduce the destination's first canonical activation publishing an
      // empty snapshot while main streams the source history into the durable
      // branch. A live-scope listener ensures a starter at this boundary unless
      // the branch handoff remains pending.
      useChatStore.setState((state) => ({
        worktreeChats: {
          ...state.worktreeChats,
          [destinationKey]: { tabs: [], activeTabId: '' },
        },
      }));
      await useChatStore.getState().ensureWorktreeHasChatTab({
        projectId: request.projectId,
        worktreeId: request.destinationWorktreeId,
      });
      destinationTabCountDuringCanonicalActivation =
        useChatStore.getState().worktreeChats[destinationKey]?.tabs.length ?? 0;
      useChatStore.setState((state) => ({
        worktreeChats: {
          ...state.worktreeChats,
          [destinationKey]: stagedDestination,
        },
      }));
      return { tabBindings: {}, selectedTabApprovalMode: 'ask' };
    });
    useChatStore.setState({
      selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
      worktreeChats: {
        'project/worktree': {
          activeTabId: 'chat',
          tabs: [
            makeTab({
              id: 'chat',
              title: 'Branch source',
              messages: [
                {
                  id: 'msg-1',
                  role: 'user',
                  blocks: [{ type: 'text', text: 'Hello' }],
                  timestamp: 1,
                },
                {
                  id: 'empty-assistant-tail',
                  role: 'assistant',
                  blocks: [{ type: 'text', text: '' }],
                  timestamp: 2,
                },
              ],
            }),
          ],
        },
      },
    });

    await useChatStore.getState().branchTab('chat');

    expect(destinationTabCountDuringRegistration).toBe(0);
    expect(destinationTabCountDuringCanonicalActivation).toBe(0);
    expect(forkOpenWorktreeTabsMock).toHaveBeenCalledTimes(1);
    const branchRequest = forkOpenWorktreeTabsMock.mock.calls[0]?.[0];
    expect(branchRequest).toMatchObject({
      projectId: 'project',
      sourceWorktreeId: 'worktree',
      destinationWorktreeId: 'branched-worktree',
      selectedTab: {
        sourceTabId: 'chat',
        throughMessageId: 'msg-1',
        destinationTab: {
          title: 'Branch source',
          forkedFrom: {
            atMessageId: 'msg-1',
          },
          messages: [],
        },
      },
    });
  });

  it('preserves the staged branch while delayed empty revisioned hydration resolves', async () => {
    const { useChatStore } = loadChatStore();
    const projectsStore = jest.requireActual<typeof ProjectsStoreModule>(
      '../stores/projectsStore',
    );
    let resolveEmptySnapshot: (() => void) | undefined;
    let destinationHydration:
      | Promise<'installed' | 'unavailable' | 'failed'>
      | undefined;
    let destinationTabCountAfterHydration = -1;
    const getStateMock = jest.fn(
      () =>
        new Promise<ChatStateSnapshot>((resolve) => {
          resolveEmptySnapshot = (): void => {
            resolve({
              schemaVersion: 1,
              projectId: 'project',
              worktreeId: 'branched-worktree',
              revision: 0,
              tabsFile: { version: 1, tabs: [], activeTabId: '' },
              archives: [],
              runtimeByChatId: {},
              queue: [],
            });
          };
        }),
    );
    Object.defineProperty(window, 'api', {
      configurable: true,
      value: {
        ...window.api,
        chat: { ...window.api.chat, getState: getStateMock },
      },
    });

    type CreateWorktree = ReturnType<
      typeof projectsStore.useProjectsStore.getState
    >['createWorktree'];
    const createWorktreeMock = jest.fn<
      ReturnType<CreateWorktree>,
      Parameters<CreateWorktree>
    >((_projectId, options) => {
      options?.onRegistered?.({
        id: 'branched-worktree',
        branchName: 'branched-worktree',
        createdAt: '2026-09-16T12:00:00.000Z',
      });
      // Registration starts hydration, but the empty canonical snapshot lands
      // only after branchTab has staged its destination tab locally.
      destinationHydration = useChatStore
        .getState()
        .hydrateChatScopeRevisioned('project', 'branched-worktree');
      return Promise.resolve({ id: 'branched-worktree' });
    });
    projectsStore.useProjectsStore.setState({
      createWorktree: createWorktreeMock,
      refreshWorktreeDiffStatsVerified: jest.fn().mockResolvedValue(true),
    });

    forkOpenWorktreeTabsMock.mockImplementationOnce(async (request) => {
      const destinationKey = `${request.projectId}/${request.destinationWorktreeId}`;
      const stagedDestination =
        useChatStore.getState().worktreeChats[destinationKey];
      if (!stagedDestination) {
        throw new Error('Expected the branched tab to be staged locally');
      }
      for (let index = 0; index < 5 && !resolveEmptySnapshot; index += 1) {
        await Promise.resolve();
      }
      if (!resolveEmptySnapshot || !destinationHydration) {
        throw new Error('Expected pending destination hydration');
      }
      resolveEmptySnapshot();
      await destinationHydration;
      destinationTabCountAfterHydration =
        useChatStore.getState().worktreeChats[destinationKey]?.tabs.length ?? 0;
      // Model the canonical tab.created delta that follows the snapshot.
      useChatStore.setState((state) => ({
        worktreeChats: {
          ...state.worktreeChats,
          [destinationKey]: stagedDestination,
        },
      }));
      return { tabBindings: {}, selectedTabApprovalMode: 'ask' };
    });
    useChatStore.setState({
      selectedWorktree: { projectId: 'project', worktreeId: 'worktree' },
      worktreeChats: {
        'project/worktree': {
          activeTabId: 'chat',
          tabs: [
            makeTab({
              id: 'chat',
              title: 'Branch source',
              messages: [
                {
                  id: 'msg-1',
                  role: 'user',
                  blocks: [{ type: 'text', text: 'Hello' }],
                  timestamp: 1,
                },
              ],
            }),
          ],
        },
      },
    });

    await useChatStore.getState().branchTab('chat');

    expect(getStateMock).toHaveBeenCalledWith({
      projectId: 'project',
      worktreeId: 'branched-worktree',
    });
    expect(destinationTabCountAfterHydration).toBe(0);
    const destinationTabs =
      useChatStore.getState().worktreeChats['project/branched-worktree']?.tabs;
    expect(destinationTabs).toHaveLength(1);
    expect(destinationTabs?.[0]).toMatchObject({
      title: 'Branch source',
      forkedFrom: { chatId: 'chat' },
    });
  });

