  it('creates no tab when message content is replaced under the same ids', async () => {
    // `mergePersistedPromptMessages` can swap content in place without changing
    // the message count or the last message id, so a count+id fingerprint alone
    // would pass and the summary would describe text the transcript no longer
    // contains.
    const { useChatStore } = seedClaudeChat({ interfaceMode: undefined });
    let resolveSummary: (value: { summary: string }) => void = () => {};
    generateHandoffSummaryMock.mockImplementationOnce(
      () =>
        new Promise<{ summary: string }>((resolve) => {
          resolveSummary = resolve;
        }),
    );

    const pending = useChatStore
      .getState()
      .continueTabOnProvider('chat', 'gpt-5.5');
    await waitForHandoffSummaryCall();

    useChatStore.setState((state) => {
      const wc = state.worktreeChats['project/worktree'];
      if (!wc) return state;
      const [tab] = wc.tabs;
      if (!tab || tab.kind === 'file') return state;
      return {
        worktreeChats: {
          ...state.worktreeChats,
          'project/worktree': {
            ...wc,
            tabs: [
              {
                ...tab,
                // Same ids, same count, same order — only the text differs.
                messages: tab.messages.map((message) => ({
                  ...message,
                  blocks: [
                    {
                      type: 'text' as const,
                      text: 'Completely different now.',
                    },
                  ],
                })),
              },
              ...wc.tabs.slice(1),
            ],
          },
        },
      };
    });

    resolveSummary({ summary: 'A summary of text that no longer exists.' });
    const result = await pending;

    expect(result.status).toBe('failed');
    expect(
      useChatStore.getState().worktreeChats['project/worktree']?.tabs,
    ).toHaveLength(1);
  });

