  it('settles a paused turn timer the continued chat can never resume', async () => {
    // A fork may leave a paused timer open because the forked chat can resume
    // the session that paused it. A continued chat runs on the other harness
    // with a new session, so the same timer would tick as unfinished forever.
    const { useChatStore } = seedClaudeChat({
      interfaceMode: undefined,
      messages: [
        {
          id: 'msg-1',
          role: 'user',
          blocks: [{ type: 'text', text: 'Fix the archive spec' }],
          timestamp: 1,
        },
        {
          id: 'msg-2',
          role: 'assistant',
          blocks: [
            { type: 'text', text: 'Working on it.' },
            {
              type: 'turn_timer',
              startedAt: 1,
              pausedAt: 2,
              completedAt: null,
            },
          ],
          timestamp: 2,
        },
      ],
    });

    const result = await useChatStore
      .getState()
      .continueTabOnProvider('chat', 'gpt-5.5');

    expect(result.status).toBe('created');
    const continued = continuedTab(useChatStore);
    const timers = (continued?.messages ?? []).flatMap((message) =>
      message.blocks.filter((block) => block.type === 'turn_timer'),
    );
    expect(timers.length).toBeGreaterThan(0);
    for (const timer of timers) {
      expect(timer.completedAt).not.toBeNull();
    }
  });

